function localAIDraft(task,context){var t=String(task||'').trim(),c=String(context||'').trim();var lines=[];lines.push('TECH4FUTURE-GLOBAL AI DRAFT');lines.push('');lines.push('Purpose / Request');lines.push(t||'Draft assistance requested.');lines.push('');if(c){lines.push('Authorized Context');lines.push(c.slice(0,6000));lines.push('');}lines.push('Recommended Structure');lines.push('1. Executive Summary');lines.push('2. Context and Rationale');lines.push('3. Objective / Intended Result');lines.push('4. Outcomes, Outputs and Key Activities');lines.push('5. Indicators, Baseline, Target and Means of Verification');lines.push('6. Stakeholders, Inclusion and Leave-No-One-Behind Considerations');lines.push('7. Budget / Resource Implications');lines.push('8. Risks, Assumptions, Safeguarding and Mitigation');lines.push('9. Implementation, Responsibilities and Timeline');lines.push('10. Monitoring, Evaluation, Learning and Reporting');lines.push('11. Decisions / Approvals Required');lines.push('12. Annexes / Evidence');lines.push('');lines.push(AI_LOCAL_DISCLAIMER);return lines.join('\n');}


function longDateTime(v){
 var d=v?new Date(v):new Date();
 return d.toLocaleString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit'});
}
function longDate(v){
 var d=v?new Date(v):new Date();
 return d.toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});
}
function weekLabel(v){
 var d=v?new Date(v):new Date(), day=(d.getDay()+6)%7, mon=new Date(d);
 mon.setDate(d.getDate()-day);
 var sun=new Date(mon);sun.setDate(mon.getDate()+6);
 return 'Week: '+mon.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})+' – '+sun.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});
}
function monthLabel(v){return (v?new Date(v):new Date()).toLocaleDateString(undefined,{month:'long',year:'numeric'});}
function avatarMini(u,cls){var pr=u&&u.profile||{};return '<div class="'+(cls||'avatar request-avatar')+'" '+avatarStyle(u||{})+'>'+((pr.photo)?'':initials(u&&u.name||'U'))+'</div>';}
function captureLocation(){
 return new Promise(function(resolve){
  if(!navigator.geolocation){resolve({status:'Unavailable'});return;}
  navigator.geolocation.getCurrentPosition(function(p){
   resolve({status:'Captured',lat:Number(p.coords.latitude.toFixed(6)),lng:Number(p.coords.longitude.toFixed(6)),accuracy:Math.round(p.coords.accuracy||0),capturedAt:nowISO()});
  },function(err){resolve({status:err&&err.code===1?'Permission denied':'Unavailable',capturedAt:nowISO()});},
  {enableHighAccuracy:true,timeout:12000,maximumAge:30000});
 });
}
function mapUrl(loc){return loc&&loc.lat!=null&&loc.lng!=null?'https://www.google.com/maps?q='+encodeURIComponent(loc.lat+','+loc.lng):'';}
function locationHtml(loc,label){
 if(!loc||loc.lat==null)return '<span class="geo-unavailable">'+esc(label||'GPS')+': '+esc(loc&&loc.status||'Not captured')+'</span>';
 return '<a class="map-link" target="_blank" rel="noopener" href="'+esc(mapUrl(loc))+'">'+esc(label||'Map')+' '+loc.lat+', '+loc.lng+'</a><small class="geo-accuracy">±'+esc(loc.accuracy||'—')+' m</small>';
}
function breakHours(t){
 return (t.breaks||[]).reduce(function(sum,b){return sum+(b.out&&b.in?hoursBetween(b.out,b.in):0);},0);
}
function workHours(t){return Math.max(0,hoursBetween(t.clockIn,t.clockOut||nowISO())-breakHours(t));}
function activeBreak(t){return t&&(t.breaks||[]).find(function(b){return b.out&&!b.in;});}
