function clone(x){return JSON.parse(JSON.stringify(x));}
function seedDB(){return {
 organizations:clone(DATA.organizations),users:[clone(INITIAL_ADMIN)],documents:clone(DATA.documents),requests:[],grants:[],contributions:[],programs:[],
 projects:[],projectTasks:[],reports:[],financeRecords:[],ledger:[],budgets:[],timeEntries:[],attendanceReports:[],audit:[],boardMeetings:[],advisoryRecommendations:[],
 documentReviews:[],documentVersions:[],reportReviews:[],projectDocuments:[],aiHistory:[],aiFiles:[],emailLog:[],settings:{createdAt:new Date().toISOString(),version:'13.0',reportPeriods:REPORT_PERIODS,controlledLibrarySource:'T4FG-LIB-004 v2.0',gpsAttendance:true,aiGovernance:true}
};}
function loadDB(){
 var raw=localStorage.getItem(STORE_KEY);
 if(raw){try{return JSON.parse(raw);}catch(e){}}
 var legacy=localStorage.getItem(LEGACY_STORE_KEY);
 if(legacy){try{
   var old=JSON.parse(legacy),n=seedDB(),oldDocs=Array.isArray(old.documents)?old.documents:[];
   Object.keys(old).forEach(function(k){if(k!=='documents')n[k]=old[k];});
   n.documents=clone(DATA.documents);
   n.documents.forEach(function(d){var match=oldDocs.find(function(x){return x.name===d.name;});if(match){
     ['status','sensitivity','version','uploadedFileName','uploadedAt','uploadedBy'].forEach(function(k){if(match[k])d[k]=match[k];});
     d.workflowStatus=match.workflowStatus||match.status||d.workflowStatus;d.legacyBlobId=match.id;
   }});
   n.documentReviews=n.documentReviews||[];n.documentVersions=n.documentVersions||[];
   ['projects','projectTasks','reports','financeRecords','ledger','budgets','timeEntries','attendanceReports','audit','requests','grants','contributions','programs','users','documentReviews','documentVersions','reportReviews','projectDocuments','aiHistory','aiFiles','emailLog'].forEach(function(k){if(!Array.isArray(n[k]))n[k]=[];});
   n.settings=n.settings||{};n.settings.version='13.0';n.settings.controlledLibrarySource='T4FG-LIB-004 v2.0';n.settings.gpsAttendance=true;n.settings.aiGovernance=true;return n;
 }catch(e2){}}
 return seedDB();
}
var db=loadDB();
DATA.organizations.forEach(function(o){if(!db.organizations.some(function(x){return x.id===o.id;}))db.organizations.push(clone(o));});
(function reconcileOfficialLibrary(){
 var existing=Array.isArray(db.documents)?db.documents:[];
 db.documents=DATA.documents.map(function(c){var x=existing.find(function(e){return e.id===c.id||e.name===c.name;});var d=clone(c);if(x){
  ['status','workflowStatus','sensitivity','version','uploadedFileName','uploadedAt','uploadedBy','owner','approvalAuthority','reviewCycle','countryApplicability','workingSummary','changeNotes','effectiveDate','publishedAt','publishedBy','legacyBlobId'].forEach(function(k){if(x[k]!=null&&x[k]!=='')d[k]=x[k];});
  if(x.id!==c.id)d.legacyBlobId=x.id;
 }return d;});
})();
['projects','projectTasks','reports','financeRecords','ledger','budgets','timeEntries','attendanceReports','audit','requests','grants','contributions','programs','users','documentReviews','documentVersions','reportReviews','projectDocuments','aiHistory','aiFiles','emailLog'].forEach(function(k){if(!Array.isArray(db[k]))db[k]=[];});

function ensureInitialPlatformAccess(){
 db.settings=db.settings||{};
 if(Number(db.settings.initialAdminCredentialVersion||0)>=1)return;
 var u=db.users.find(function(x){return String(x.email||'').toLowerCase()===INITIAL_ADMIN.email;});
 if(!u){
   u=clone(INITIAL_ADMIN);
   db.users.unshift(u);
 }else{
   u.orgId=INITIAL_ADMIN.orgId;
   u.email=INITIAL_ADMIN.email;
   u.password=INITIAL_ADMIN.password;
   u.systemRole='platform_super_admin';
   u.positionId=u.positionId||INITIAL_ADMIN.positionId;
   u.status='Active';
   u.mustReset=true;
   u.profile=u.profile||clone(INITIAL_ADMIN.profile);
 }
 db.settings.initialAdminCredentialVersion=1;
 db.settings.initialAdminCredentialConsumed=false;
 db.settings.initialAdminCredentialIssuedAt=new Date().toISOString();
}
ensureInitialPlatformAccess();
