var $=function(s){return document.querySelector(s);};
var $$=function(s){return Array.prototype.slice.call(document.querySelectorAll(s));};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m];});}
function initials(s){return String(s||'U').split(/\s+/).filter(Boolean).map(function(x){return x[0];}).slice(0,2).join('').toUpperCase();}
function slug(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n||0));}
function nowISO(){return new Date().toISOString();}
function orgById(id){return db.organizations.find(function(o){return o.id===id;});}
function userById(id){return db.users.find(function(u){return u.id===id;});}
