function statusPill(s){return '<span class="status '+slug(s)+'">'+esc(s)+'</span>';}
function toast(msg){var t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(function(){t.classList.remove('show');},2800);}
function uuid(){return (window.crypto&&crypto.randomUUID)?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(16).slice(2);}
function logAction(action,detail,orgId){orgId=orgId||session&&session.orgId;db.audit.unshift({id:uuid(),time:nowISO(),actor:session&&session.name||'System',userId:session&&session.id||'',organization:orgById(orgId)&&orgById(orgId).name||'Platform',action:action,detail:detail});db.audit=db.audit.slice(0,1000);save();}
function randomPassword(){var chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%*+-_';var out='';var a=new Uint32Array(16);crypto.getRandomValues(a);for(var i=0;i<a.length;i++)out+=chars[a[i]%chars.length];return out;}
function randomPin(){var a=new Uint32Array(1);crypto.getRandomValues(a);return String(a[0]%1000000).padStart(6,'0');}
function isPlatformAdmin(){return session&&session.systemRole==='platform_super_admin';}
function isHighAdmin(){return !!session&&['platform_super_admin','high_super_admin','country_super_admin'].indexOf(session.systemRole)>=0;}
function isCountryOrg(orgId){return orgById(orgId||session&&session.orgId)&&orgById(orgId||session&&session.orgId).type==='country_office';}
function isFiscalUser(){return orgById(session&&session.orgId)&&orgById(session.orgId).type==='fiscal_sponsor';}
function isExternalUser(){var o=orgById(session&&session.orgId);return o&&['donor','regular_sponsor','supporter','partner'].indexOf(o.type)>=0;}
function isClockUser(){var f=positionFamily();return ['board','advisory','global_management','global_employee','regional','country','volunteer'].indexOf(f)>=0&&!isFiscalUser()&&!isExternalUser();}
function isProjectTeam(){return PROJECT_TEAM_POSITIONS.indexOf(session&&session.positionId)>=0;}
function isProjectHead(){return PROJECT_HEAD_POSITIONS.indexOf(session&&session.positionId)>=0||isPlatformAdmin();}
function isCountryITProvisioner(){return isCountryOrg()&&(COUNTRY_IT_POSITIONS.indexOf(session.positionId)>=0||session.systemRole==='country_it_admin');}
function canProvisionUsers(){return isPlatformAdmin()||session&&session.systemRole==='high_super_admin'||session&&session.systemRole==='country_super_admin'||isCountryITProvisioner();}
function canManageCountryDirectorAssignment(orgId){return isPlatformAdmin()||!!(session&&session.orgId==='t4f-hq'&&session.systemRole==='high_super_admin')||!!(session&&session.orgId===orgId&&(session.systemRole==='country_super_admin'||session.systemRole==='country_it_admin'||COUNTRY_IT_POSITIONS.indexOf(session.positionId)>=0));}
function canManageStakeholders(){return isPlatformAdmin()||!!(session&&session.orgId==='t4f-hq'&&(session.systemRole==='high_super_admin'||positionFamily()==='global_management'));}
function canManageIncome(){return isPlatformAdmin()||!!(session&&session.orgId==='t4f-hq'&&(session.systemRole==='high_super_admin'||positionFamily()==='global_management'||GLOBAL_FINANCE_POSITIONS.indexOf(session.positionId)>=0));}
function canUploadControlledDocs(){return isPlatformAdmin()||!!(session&&session.orgId==='t4f-hq'&&(session.systemRole==='high_super_admin'||GLOBAL_DOC_ADMIN_POSITIONS.indexOf(session.positionId)>=0));}
function canEditControlledDocs(){return canUploadControlledDocs();}
function canApproveControlledDocs(){return isPlatformAdmin()||!!(session&&session.orgId==='t4f-hq'&&(session.systemRole==='high_super_admin'||GLOBAL_DOC_APPROVER_POSITIONS.indexOf(session.positionId)>=0));}
function canManageDocRequests(){return canUploadControlledDocs();}
function canCreateProjects(){return isInternalUser();}
function canCreateFinance(){return isPlatformAdmin()||GLOBAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||REGIONAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||COUNTRY_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0;}
function canApproveFinance(){return isPlatformAdmin()||session&&['global-director-executive-leadership','global-director-finance-administration','global-finance-manager','country-director','country-finance-administration-manager','regional-coordinator-finance-administration'].indexOf(session.positionId)>=0;}
function canPostFinance(){return isPlatformAdmin()||GLOBAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||REGIONAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||session&&session.positionId==='country-finance-administration-manager';}
function globalFinanceRead(){var f=positionFamily();return isPlatformAdmin()||f==='board'||f==='advisory'||f==='global_management'||GLOBAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||REGIONAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0;}
