function canSeeFinance(){return globalFinanceRead()||COUNTRY_EXECUTIVE_POSITIONS.indexOf(session&&session.positionId)>=0||COUNTRY_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||isProjectTeam();}
function canSeeBookkeeping(){return globalFinanceRead()||GLOBAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||REGIONAL_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||COUNTRY_FINANCE_POSITIONS.indexOf(session&&session.positionId)>=0||COUNTRY_EXECUTIVE_POSITIONS.indexOf(session&&session.positionId)>=0;}
function canSeeBudgets(){return canSeeFinance()||isProjectTeam();}
function visibleOrgIds(){
 if(isPlatformAdmin())return viewedOrgId&&viewedOrgId!=='t4f-hq'?[viewedOrgId]:db.organizations.filter(function(o){return o.id==='t4f-hq'||o.parentId==='t4f-hq';}).map(function(o){return o.id;});
 if(session&&session.orgId==='t4f-hq'&&session.systemRole==='high_super_admin')return db.organizations.filter(function(o){return o.id==='t4f-hq'||o.parentId==='t4f-hq';}).map(function(o){return o.id;});
 return [session&&session.orgId];
}
