 if((session.positionId==='country-director'||session.positionId==='country-finance-administration-manager')&&b.orgId===session.orgId)return true;
 if(isProjectHead()&&b.orgId===session.orgId&&(b.type==='Project'||b.type==='Program'))return true;
 return false;
