function canManageReports(){return !!session;}
function reportAudienceAllowed(r){
 if(!session)return false;
 if(isFiscalUser()||isExternalUser())return r.userId===session.id||r.orgId===session.orgId||(['Approved','Published'].indexOf(r.workflowStatus||r.status)>=0&&['Stakeholders','Public'].indexOf(r.audience)>=0);
 if(isPlatformAdmin()||positionFamily()==='board'||positionFamily()==='advisory'||positionFamily()==='global_management')return true;
 if(session.orgId==='t4f-hq')return r.orgId==='t4f-hq'||r.audience==='Global Internal'||r.audience==='Stakeholders'||r.audience==='Public';
 return r.orgId===session.orgId||r.audience==='Global Internal'||r.audience==='Stakeholders'||r.audience==='Public';
}

function moduleAccess(){
 if(!session)return[];
 if(isFiscalUser()){var fm=['dashboard','country_portals','stakeholders','reports','ai','donor_income','sponsor_income','supporter_income','partner_income','profile'];if(session.systemRole==='high_super_admin')fm.push('accounts');return fm;}
 if(isExternalUser()){var ex=['dashboard','country_portals','stakeholders','reports','ai','documents','donor_income','sponsor_income','supporter_income','partner_income','profile'];if(session.systemRole==='high_super_admin')ex.push('accounts');return ex;}
 if(isPlatformAdmin())return Object.keys(MODULES);
 var fam=positionFamily();
 var base={
  board:['dashboard','timeclock','country_portals','stakeholders','project_workspace','board','documents','reports','finance','budgets','ai','profile'],
  advisory:['dashboard','timeclock','country_portals','stakeholders','project_workspace','advisory','documents','reports','finance','budgets','ai','profile'],
  global_management:['dashboard','timeclock','organizations','accounts','positions','country_portals','stakeholders','programs','project_workspace','staff','board','advisory','documents','finance','bookkeeping','budgets','donors','sponsors','supporters','partners','donor_income','sponsor_income','supporter_income','partner_income','reports','ai','audit','profile'],
  global_employee:['dashboard','timeclock','country_portals','project_workspace','positions','programs','staff','documents','reports','ai','profile'],
  regional:['dashboard','timeclock','project_workspace','country_portals','programs','staff','documents','reports','ai','profile'],
  country:['dashboard','timeclock','country_portals','project_workspace','programs','staff','documents','reports','ai','profile'],
  volunteer:['dashboard','timeclock','country_portals','project_workspace','documents','reports','ai','profile']
 }[fam]||['dashboard','reports','documents','profile'];
 base.push('country_portals');
 if(isProjectTeam())base.push('project_workspace');
 if(canSeeFinance())base.push('finance');
 if(canSeeBookkeeping())base.push('bookkeeping');
 if(canSeeBudgets())base.push('budgets');
 if(canProvisionUsers())base.push('accounts');
 if(canManageDocRequests())base.push('requests');
 if(isHighAdmin())base.push('positions');
 if(session&&session.orgId==='t4f-hq'&&session.systemRole==='high_super_admin')base.push('data_storage');
 return Array.from(new Set(base));
}
function can(module){return moduleAccess().indexOf(module)>=0;}

/* file storage */
var fileDBPromise;
var memoryFileStore={};
function fileRecord(file,id){return {id:id,name:file&&file.name||'file',type:file&&file.type||'application/octet-stream',size:file&&file.size||0,blob:file&&file.blob?file.blob:file};}
function fileDB(){
 if(fileDBPromise)return fileDBPromise;
 fileDBPromise=new Promise(function(resolve){
  try{
   var r=indexedDB.open('t4f_v4_files',6);
   r.onupgradeneeded=function(){var d=r.result;if(!d.objectStoreNames.contains('controlledFiles'))d.createObjectStore('controlledFiles',{keyPath:'id'});if(!d.objectStoreNames.contains('reportFiles'))d.createObjectStore('reportFiles',{keyPath:'id'});if(!d.objectStoreNames.contains('controlledVersions'))d.createObjectStore('controlledVersions',{keyPath:'id'});if(!d.objectStoreNames.contains('projectFiles'))d.createObjectStore('projectFiles',{keyPath:'id'});if(!d.objectStoreNames.contains('incomeFiles'))d.createObjectStore('incomeFiles',{keyPath:'id'});if(!d.objectStoreNames.contains('aiFiles'))d.createObjectStore('aiFiles',{keyPath:'id'});if(!d.objectStoreNames.contains('attendanceFiles'))d.createObjectStore('attendanceFiles',{keyPath:'id'});};
   r.onsuccess=function(){resolve(r.result);};
   r.onerror=function(){resolve(null);};
   r.onblocked=function(){resolve(null);};
  }catch(e){resolve(null);}
 });
 return fileDBPromise;
}
async function putBlob(store,id,file){
 var rec=fileRecord(file,id),d=await fileDB();
 if(!d){memoryFileStore[store]=memoryFileStore[store]||{};memoryFileStore[store][id]=rec;return;}
 return new Promise(function(resolve){try{var tx=d.transaction(store,'readwrite');tx.objectStore(store).put(rec);tx.oncomplete=function(){resolve();};tx.onerror=function(){memoryFileStore[store]=memoryFileStore[store]||{};memoryFileStore[store][id]=rec;resolve();};}catch(e){memoryFileStore[store]=memoryFileStore[store]||{};memoryFileStore[store][id]=rec;resolve();}});
}
async function getBlob(store,id){
 var d=await fileDB();
 if(!d)return memoryFileStore[store]&&memoryFileStore[store][id]||null;
 return new Promise(function(resolve){try{var tx=d.transaction(store,'readonly'),r=tx.objectStore(store).get(id);r.onsuccess=function(){resolve(r.result||memoryFileStore[store]&&memoryFileStore[store][id]||null);};r.onerror=function(){resolve(memoryFileStore[store]&&memoryFileStore[store][id]||null);};}catch(e){resolve(memoryFileStore[store]&&memoryFileStore[store][id]||null);}});
}
async function getControlledBlob(d){var f=await getBlob('controlledFiles',d.id);if(!f&&d.legacyBlobId)f=await getBlob('controlledFiles',d.legacyBlobId);return f;}
async function archiveDocumentVersion(d,label){var f=await getControlledBlob(d);var snap={id:uuid(),docId:d.id,version:d.version||'Unversioned',status:d.workflowStatus||d.status,archivedAt:nowISO(),archivedBy:session&&session.name||'System',changeNotes:d.changeNotes||'',fileKey:'',fileName:d.uploadedFileName||''};if(f){var key=d.id+'::'+(d.version||'unversioned')+'::'+Date.now();await putBlob('controlledVersions',key,f.blob);snap.fileKey=key;}db.documentVersions.unshift(snap);return snap;}
function documentReviewsFor(docId){return db.documentReviews.filter(function(r){return r.docId===docId;}).sort(function(a,b){return String(b.createdAt).localeCompare(String(a.createdAt));});}
function documentVersionsFor(docId){return db.documentVersions.filter(function(r){return r.docId===docId;}).sort(function(a,b){return String(b.archivedAt).localeCompare(String(a.archivedAt));});}


/* setup/login */
function hydrateBackendState(state,user){
 if(state&&typeof state==='object'&&Object.keys(state).length){db=state;}
 ['organizations','users','documents','projects','projectTasks','reports','financeRecords','ledger','budgets','timeEntries','attendanceReports','audit','requests','grants','contributions','programs','documentReviews','documentVersions','reportReviews','projectDocuments','aiHistory','aiFiles','emailLog'].forEach(function(k){if(!Array.isArray(db[k]))db[k]=[];});
 DATA.organizations.forEach(function(o){if(!db.organizations.some(function(x){return x.id===o.id;}))db.organizations.push(clone(o));});
 if(user){var existing=db.users.find(function(x){return x.id===user.id||String(x.email||'').toLowerCase()===String(user.email||'').toLowerCase();});if(existing)Object.assign(existing,user);else db.users.unshift(clone(user));}
 db.settings=db.settings||{};db.settings.version='13.0';db.settings.backend='django-fastapi';
 localStorage.setItem(STORE_KEY,JSON.stringify(db));
}
async function backendLogin(org,email,pw){
 if(!window.T4FBackend)return null;
 try{var auth=await window.T4FBackend.login(org,email,pw),ws=await window.T4FBackend.getState();hydrateBackendState(ws&&ws.state,auth.user);return auth.user;}catch(err){if(err&&err.status===401)throw err;return null;}
}
function showInitialScreen(){
 $('#portalShell').classList.add('hidden');
 if(db.users.length===0){$('#setupScreen').classList.remove('hidden');$('#loginScreen').classList.add('hidden');}
 else{$('#setupScreen').classList.add('hidden');$('#loginScreen').classList.remove('hidden');fillLoginOrganizations();}
}
function fillSetupPositions(){var s=$('#setupPosition');if(!s)return;s.innerHTML=DATA.positions.filter(function(p){return ['global_management','global_employee'].indexOf(p.family)>=0;}).map(function(p){return '<option value="'+p.id+'">'+esc(p.title)+'</option>';}).join('');}
fillSetupPositions();
$('#setupForm').addEventListener('submit',function(e){e.preventDefault();var n=$('#setupName').value.trim(),email=$('#setupEmail').value.trim().toLowerCase(),p=$('#setupPassword').value,c=$('#setupConfirm').value;if(p!==c){$('#setupError').textContent='Passwords do not match.';return;}if(p.length!==8){$('#setupError').textContent='Password must be only 8 characters long.';return;}var u={id:uuid(),orgId:'t4f-hq',name:n,email:email,password:p,systemRole:'platform_super_admin',positionId:$('#setupPosition').value,status:'Active',mustReset:false,profile:emptyProfile('United States')};db.users.push(u);save();session=clone(u);sessionStorage.setItem(SESSION_KEY,JSON.stringify({id:u.id}));logAction('Platform initialized','Platform Super Administrator created','t4f-hq');openPortal();});

function fillInitialAdminLogin(){
 var org=$('#loginOrg'),email=$('#loginEmail'),pw=$('#loginPassword');
 if(org)org.value='t4f-hq';
 if(email)email.value=INITIAL_ADMIN.email;
 if(pw)pw.value=INITIAL_ADMIN.password;
 var e=$('#loginError');if(e)e.textContent='';
}
function fillLoginOrganizations(){var ids={};db.users.filter(function(u){return u.status!=='Inactive';}).forEach(function(u){ids[u.orgId]=true;});$('#loginOrg').innerHTML=db.organizations.filter(function(o){return ids[o.id];}).map(function(o){return '<option value="'+o.id+'">'+esc(o.name)+'</option>';}).join('');}
$('#loginForm').addEventListener('submit',async function(e){e.preventDefault();var org=$('#loginOrg').value,email=$('#loginEmail').value.trim().toLowerCase(),pw=$('#loginPassword').value,u=null;try{u=await backendLogin(org,email,pw);}catch(authErr){$('#loginError').textContent='Invalid organization, email, or password.';return;}if(!u){u=db.users.find(function(x){return x.orgId===org&&x.email.toLowerCase()===email&&x.password===pw&&x.status!=='Inactive';});}if(!u){$('#loginError').textContent='Invalid organization, email, or password. If the server is online, verify the Django account credentials and organization.';return;}session=clone(u);viewedOrgId=u.orgId;sessionStorage.setItem(SESSION_KEY,JSON.stringify({id:u.id}));logAction('Signed in','Portal access',u.orgId);openPortal();if(u.mustReset)forcePasswordChange();});
$('#logoutBtn').addEventListener('click',async function(){if(session)logAction('Signed out','Session ended',session.orgId);if(window.T4FBackend)await window.T4FBackend.logout();session=null;sessionStorage.removeItem(SESSION_KEY);showInitialScreen();});
function emptyProfile(country){return {photo:'',phone:'',country:country||'',city:'',bio:'',education:'',qualifications:'',certifications:'',experience:'',appointmentDate:'',termStart:'',termEnd:'',linkedin:'',officeAddress:'',fax:''};}

/* portal shell */
function openPortal(){$('#setupScreen').classList.add('hidden');$('#loginScreen').classList.add('hidden');$('#portalShell').classList.remove('hidden');applySessionLabels();configureOrgSwitcher();currentPage='dashboard';buildNav();render('dashboard');startClockTicker();}
function applySessionLabels(){var u=userById(session.id)||session,o=orgById(u.orgId),p=positionById(u.positionId),pr=u.profile||{};$('#orgTypeLabel').textContent=(o&&o.type||'ORGANIZATION').replace(/_/g,' ').toUpperCase();$('#orgNameLabel').textContent=o&&o.name||'';$('#positionLabel').textContent=p&&p.title||specialPositionLabel(u);$('#sidebarName').textContent=u.name;$('#sidebarEmail').textContent=u.email;setAvatar($('#sidebarAvatar'),u);setAvatar($('#topAvatar'),u);}
function setAvatar(el,u){var photo=u&&u.profile&&u.profile.photo;el.style.backgroundImage=photo?'url("'+photo.replace(/"/g,'')+'")':'';el.textContent=photo?'':initials(u&&u.name);}
function specialPositionLabel(u){if(!u)return'';if(u.systemRole==='platform_super_admin')return'Platform Super Administrator';if(u.systemRole==='high_super_admin')return'High Super Administrator';if(u.systemRole==='country_super_admin')return'Country Super Administrator';if(u.systemRole==='country_it_admin')return'Country IT Account Administrator';if(isFiscalUser())return'Fiscal Sponsor Authorized User';return'Authorized User';}
function configureOrgSwitcher(){var wrap=$('#orgSwitchWrap'),s=$('#orgSwitch');var allow=isPlatformAdmin()||session.orgId==='t4f-hq'&&session.systemRole==='high_super_admin';wrap.classList.toggle('hidden',!allow);if(!allow)return;var orgs=isPlatformAdmin()?db.organizations:db.organizations.filter(function(o){return o.id==='t4f-hq'||o.parentId==='t4f-hq';});s.innerHTML=orgs.map(function(o){return '<option value="'+o.id+'">'+esc(o.name)+'</option>';}).join('');s.value=viewedOrgId||session.orgId;s.onchange=function(){viewedOrgId=s.value;render(currentPage);};}
function buildNav(){var allowed=moduleAccess(),groups={};allowed.forEach(function(m){if(!MODULES[m]||MODULES[m].hidden)return;var g=MODULES[m].group;if(!groups[g])groups[g]=[];groups[g].push(m);});var html='';Object.keys(groups).forEach(function(g){html+='<div class="nav-group">'+esc(g.toUpperCase())+'</div>';groups[g].forEach(function(m){html+='<button class="nav-item '+(currentPage===m?'selected':'')+'" data-page="'+m+'"><span class="nav-icon">'+MODULES[m].icon+'</span><span>'+esc(MODULES[m].label)+'</span></button>';});});$('#sideNav').innerHTML=html;$$('#sideNav .nav-item').forEach(function(b){b.addEventListener('click',function(){go(b.getAttribute('data-page'));});});}
function go(page){if(!can(page)){toast('Your assigned position does not have access to that module.');return;}currentPage=page;buildNav();render(page);window.scrollTo({top:0,behavior:'smooth'});}
$('#profileButton').onclick=function(){go('profile');};
document.addEventListener('keydown',function(e){
 if(e.altKey&&e.shiftKey&&String(e.key).toLowerCase()==='d'&&session&&can('data_storage')){
  e.preventDefault();go('data_storage');
 }
});

function forcePasswordChange(){forceReset=true;showModal('SECURITY','Change temporary password','<form id="forceResetForm" class="form-grid"><div class="credential-box full"><b>First sign-in:</b> replace the temporary password before continuing. (Must be only 8 characters long)</div><label class="full">New password<input id="newPassword" type="password" minlength="8" maxlength="8" required></label><label class="full">Confirm password<input id="newPassword2" type="password" minlength="8" maxlength="8" required></label><div id="resetError" class="form-error full"></div><div class="form-actions"><button class="btn primary">Set new password</button></div></form>');$('#modalClose').classList.add('hidden');$('#forceResetForm').onsubmit=async function(e){e.preventDefault();var p=$('#newPassword').value,c=$('#newPassword2').value;if(p!==c){$('#resetError').textContent='Passwords do not match.';return;}if(p.length!==8){$('#resetError').textContent='Password must be only 8 characters long.';return;}try{if(window.T4FBackend&&window.T4FBackend.token())await window.T4FBackend.changePassword('',p);}catch(err){$('#resetError').textContent=err.message||'Password update failed.';return;}var u=userById(session.id);if(u){u.password=p;u.mustReset=false;u.status='Active';}db.settings=db.settings||{};if(u&&String(u.email||'').toLowerCase()===INITIAL_ADMIN.email){db.settings.initialAdminCredentialConsumed=true;db.settings.initialAdminCredentialConsumedAt=nowISO();}session=clone(u||session);save();logAction('Changed temporary password','First-login reset completed');forceReset=false;$('#modalClose').classList.remove('hidden');closeModal();toast('Password updated.');};}

