function activatePlatformControls(){
  var root=document;
  $$('.btn,button,[role="button"],a.btn').forEach(function(el){
    if(el.hasAttribute('data-permission-disabled'))return;
    el.style.pointerEvents='auto';
    el.style.cursor='pointer';
    if(!el.hasAttribute('tabindex')&&el.tagName!=='BUTTON'&&el.tagName!=='A')el.setAttribute('tabindex','0');
  });
  $$('.btn[onclick],button[onclick],a.btn[onclick]').forEach(function(el){el.removeAttribute('disabled');el.setAttribute('aria-disabled','false');});
}

