function sanitizedPersistentState(){
 var x=clone(db);
 (x.users||[]).forEach(function(u){delete u.password;delete u.passwordHash;});
 (x.requests||[]).forEach(function(r){delete r.pin;});
 if(x.settings){delete x.settings.apiKey;delete x.settings.databaseToken;}
 return x;
}
function mergeLocalCredentials(restored){
 var localById={};(db.users||[]).forEach(function(u){if(u.password)localById[u.id]=u.password;});
 (restored.users||[]).forEach(function(u){if(localById[u.id])u.password=localById[u.id];else if(!u.password){u.status=u.status==='Active'?'Pending Invitation':u.status;u.mustReset=true;}});
 return restored;
}
function dbSyncToken(){return sessionStorage.getItem('t4f_v9_db_sync_token')||'';}
function setDbSyncToken(v){if(v)sessionStorage.setItem('t4f_v9_db_sync_token',v);else sessionStorage.removeItem('t4f_v9_db_sync_token');}
function localRecordCount(){return Object.keys(db).reduce(function(n,k){return n+(Array.isArray(db[k])?db[k].length:0);},0);}
function renderDataStorage(){
 if(!isPlatformAdmin()&&!(session&&session.orgId==='t4f-hq'&&session.systemRole==='high_super_admin'))return pageHeader('DATABASE','Access Denied','Database administration is restricted to the Platform Super Administrator and authorized HQ High Super Administrator.');
 setTimeout(refreshDatabaseStatus,50);
 return pageHeader('DATA SECURITY & SCALE','Database & Storage','Large-record persistence dashboard for PostgreSQL, browser storage, database snapshots, recovery, AI files and platform backups.')+
 '<div class="kpis">'+kpi('LOCAL STRUCTURED RECORDS',String(localRecordCount()),'Current browser workspace')+kpi('POSTGRESQL','Checking…','Server database status')+kpi('AI FILES',String((db.aiFiles||[]).length),'Word / Excel exports')+kpi('AUDIT EVENTS',String((db.audit||[]).length),'Local audit trail')+'</div>'+
 '<div class="grid-2 db-storage-grid"><div class="card panel"><div class="panel-head"><h4>PostgreSQL Connection</h4><span id="dbConnectionBadge">Checking server…</span></div><div id="dbStatusBox" class="db-status-box">Checking database health and record capacity…</div><label class="db-token-label">Database Sync Token<input id="dbSyncTokenInput" type="password" value="'+esc(dbSyncToken())+'" placeholder="Server T4F_DB_SYNC_TOKEN"></label><div class="form-actions"><button class="btn secondary" onclick="refreshDatabaseStatus()">Refresh Status</button><button class="btn primary" onclick="syncPlatformDatabase()">Sync Current Workspace</button><button class="btn" onclick="restorePlatformDatabase()">Restore Latest Snapshot</button></div></div>'+
 '<div class="card panel"><div class="panel-head"><h4>Backup & Reliability</h4><span>Administrative controls</span></div><div class="check-stack"><span>✓ PostgreSQL normalized core tables</span><span>✓ Flexible JSONB high-volume records</span><span>✓ Indexed search fields</span><span>✓ Snapshot recovery</span><span>✓ Audit/event storage</span><span>✓ File metadata and AI export records</span><span>✓ Row-Level Security foundation</span></div><div class="form-actions"><button class="btn" onclick="downloadPlatformBackup()">Download JSON Backup</button><button class="btn secondary" onclick="runInterfaceSelfTest()">Run Interface Self-Test</button></div><div id="selfTestResults" class="self-test-results"></div></div></div>'+
 sectionHead('DATABASE DESIGN','High-volume secure record architecture','The browser remains usable offline, while the server can persist synchronized data to PostgreSQL. Production should use HTTPS, server-side identity, MFA, least-privilege DB accounts, encrypted storage and backups.')+
 '<div class="cards"><div class="card mini-card"><div class="iconbox">DB</div><h4>Core Records</h4><p>Organizations, users, projects, reports, controlled documents, finance, ledger, budgets and attendance.</p></div><div class="card mini-card"><div class="iconbox">JS</div><h4>Flexible Records</h4><p>Indexed JSONB record storage supports future modules without redesigning the entire database.</p></div><div class="card mini-card"><div class="iconbox">DR</div><h4>Recovery</h4><p>Workspace snapshots support restore and disaster-recovery workflows alongside normal backups.</p></div></div>';
}
async function refreshDatabaseStatus(){
 var box=$('#dbStatusBox'),badge=$('#dbConnectionBadge');if(!box)return;
 try{var r=await fetch('/api/db/status'),j=await r.json();if(j.connected){badge.textContent='Connected';badge.className='status active';box.innerHTML='<b>PostgreSQL connected</b><span>Latency: '+esc(j.latency_ms)+' ms</span><span>Platform records: '+esc(j.platform_records||0)+'</span><span>Snapshots: '+esc(j.snapshots||0)+'</span><span>File records: '+esc(j.files||0)+'</span><span>Audit events: '+esc(j.audit_events||0)+'</span>';}else{badge.textContent=j.configured?'Unavailable':'Not configured';badge.className='status pending';box.innerHTML='<b>'+esc(j.configured?'Database connection unavailable':'PostgreSQL is not configured on this server')+'</b><span>'+esc(j.error||'Browser-only mode remains available.')+'</span>';}}catch(e){badge.textContent='Server unavailable';badge.className='status pending';box.innerHTML='<b>Server database status could not be reached.</b><span>Standalone browser storage remains active.</span>';}
}
async function syncPlatformDatabase(){
 var input=$('#dbSyncTokenInput'),token=(input&&input.value.trim())||dbSyncToken();if(!token){toast('Enter the server database sync token first.');return;}setDbSyncToken(token);
 if(!window.confirm('Synchronize the current browser workspace to the PostgreSQL database and create a recovery snapshot?'))return;
 toast('Synchronizing platform records…');
 try{var r=await fetch('/api/db/sync',{method:'POST',headers:{'Content-Type':'application/json','x-t4f-db-token':token},body:JSON.stringify({workspaceId:'t4f-global',state:sanitizedPersistentState(),createdBy:session.id})}),j=await r.json();if(!r.ok)throw new Error(j.error||'Database sync failed');logAction('Synchronized platform database',(j.snapshot_saved?'Revision '+j.revision:'Record sync without snapshot')+' • '+j.record_types+' record types','t4f-hq');toast(j.snapshot_saved?'Database synchronization completed. Revision '+j.revision+'.':'Database records synchronized. The workspace exceeded the configured snapshot size limit, so no full snapshot was stored.');refreshDatabaseStatus();}catch(e){toast(e.message||'Database synchronization failed.');}
}
async function restorePlatformDatabase(){
 var input=$('#dbSyncTokenInput'),token=(input&&input.value.trim())||dbSyncToken();if(!token){toast('Enter the server database sync token first.');return;}setDbSyncToken(token);
 if(!window.confirm('Restore the latest PostgreSQL snapshot into this browser? Current unsynchronized browser changes will be replaced.'))return;
 try{var r=await fetch('/api/db/snapshot?workspaceId=t4f-global',{headers:{'x-t4f-db-token':token}}),j=await r.json();if(!r.ok)throw new Error(j.error||'Restore failed');if(!j.state)throw new Error('Snapshot contains no state');db=mergeLocalCredentials(j.state);save();localStorage.setItem(STORE_KEY,JSON.stringify(db));logAction('Restored database snapshot','Revision '+j.revision,'t4f-hq');toast('Database snapshot restored. Reloading portal…');setTimeout(function(){location.reload();},800);}catch(e){toast(e.message||'Database restore failed.');}
}
function downloadPlatformBackup(){
 var blob=new Blob([JSON.stringify({platform:'Tech4Future-Global',version:PLATFORM_VERSION,exportedAt:nowISO(),state:sanitizedPersistentState()},null,2)],{type:'application/json'});downloadBlob(blob,'Tech4Future-Global-V'+PLATFORM_VERSION+'-Backup-'+new Date().toISOString().slice(0,10)+'.json');logAction('Downloaded platform backup','JSON administrative backup','t4f-hq');
}
function runInterfaceSelfTest(){
 var required=['go','openUserModal','openOrganizationModal','openProjectModal','openProjectDocumentModal','openReportModal','openAIAssistant','openDocumentUpload','openDocumentReview','openDocumentEditor','openFinanceMenu','openFinanceRecordModal','openBudgetModal','sendAccountInvitation','editUserAccount','deleteUserAccount','deleteProject','deleteReport','deleteFinanceRecord','syncPlatformDatabase'],failed=required.filter(function(x){return typeof window[x]!=='function';}),out=$('#selfTestResults');if(out)out.innerHTML=failed.length?'<div class="self-test fail"><b>Action wiring issue detected</b><span>'+esc(failed.join(', '))+'</span></div>':'<div class="self-test pass"><b>PASS — core action handlers are active</b><span>'+required.length+' critical click/add/edit/delete/invite/save controls verified in the running page.</span></div>';return !failed.length;
}

