function renderPositions(){var groups=Array.from(new Set(DATA.positions.map(function(p){return p.group;}))),p=positionById(selectedPositionId)||DATA.positions[0];return pageHeader('LEADERSHIP HIERARCHY','Positions & Terms of Reference','The complete Board, Advisory Council, global, regional, country and volunteer hierarchy remains the source of position-based portal behavior.')+sectionHead('CONTROLLED POSITION ROSTER',DATA.positions.length+' positions','Select a position to review its reporting line and TOR.')+'<div class="position-browser"><div class="card position-list">'+groups.map(function(g){return '<div class="nav-group" style="color:#7d8ba0">'+esc(g.toUpperCase())+'</div>'+DATA.positions.filter(function(x){return x.group===g;}).map(function(x){return '<button class="'+(x.id===p.id?'selected':'')+'" onclick="selectPosition(\''+x.id+'\')"><b>'+esc(x.title)+'</b><small>'+esc(x.family.replace(/_/g,' '))+'</small></button>';}).join('');}).join('')+'</div><div class="card panel">'+torFull(p)+'</div></div>';}
function selectPosition(id){selectedPositionId=id;render('positions');}
function torSummary(id){var p=positionById(id);if(!p)return '<div class="empty"><b>No hierarchy position assigned</b></div>';return '<div class="tor-section"><h4>'+esc(p.title)+'</h4><p><b>Reports to:</b> '+esc(p.reportsTo||'')+'</p><p>'+esc(p.rolePurpose||'')+'</p></div>';}
function torFull(p){if(!p)return '<div class="empty"><b>No Terms of Reference attached</b>This external/system role does not use a hierarchy TOR.</div>';function list(title,arr){return arr&&arr.length?'<div class="tor-section"><h4>'+title+'</h4><ul>'+arr.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul></div>':'';}return '<div class="tor-section"><h4>'+esc(p.title)+'</h4><p><b>'+esc(p.descriptor||'')+'</b></p><p>'+esc(p.rolePurpose||'')+'</p></div>'+list('Core responsibilities',p.coreResponsibilities)+list('Authority & limits',p.authorityLimits)+(p.supervisionCoordination?'<div class="tor-section"><h4>Supervision / coordination</h4><p>'+esc(p.supervisionCoordination)+'</p></div>':'')+list('Key outputs & success measures',p.outputs)+list('Minimum profile',p.minimumProfile);}

