function hasReviewAccess(d){if(isPlatformAdmin())return true;var fam=positionFamily();if(['board','advisory','global_management'].indexOf(fam)>=0)return true;if(db.grants.some(function(g){return g.active&&g.userId===session.id&&g.docId===d.id&&g.type==='review';}))return true;return false;}
