/* time clock */
function activeClock(){return db.timeEntries.find(function(t){return t.userId===session.id&&!t.clockOut;});}
function todayEntries(userId){var d=new Date().toISOString().slice(0,10);return db.timeEntries.filter(function(t){return t.userId===userId&&String(t.clockIn).slice(0,10)===d;});}
function hoursBetween(a,b){return Math.max(0,(new Date(b)-new Date(a))/3600000);}
function weeklyHours(userId){var now=new Date(),start=new Date(now);start.setDate(now.getDate()-6);return db.timeEntries.filter(function(t){return t.userId===userId&&new Date(t.clockIn)>=start;}).reduce(function(sum,t){return sum+workHours(t);},0);}
function clockWidget(){var a=activeClock(),br=activeBreak(a),today=todayEntries(session.id),hours=today.reduce(function(s,t){return s+workHours(t);},0),u=userById(session.id);return sectionHead('TIME & ATTENDANCE','Employee Time Clock','Detailed check-in, break-out, break-in and clock-out with profile photo, spelled-out date and optional GPS evidence.')+'<div class="clock-v7"><div class="clock-person">'+avatarMini(u,'clock-photo')+'<div><span>EMPLOYEE</span><b>'+esc(u&&u.name||session.name)+'</b><small>'+esc(positionTitle(u))+'</small></div></div><div class="clock-face"><span id="liveClock">'+new Date().toLocaleTimeString()+'</span><small>'+longDate()+'</small><em>'+weekLabel()+' • '+monthLabel()+'</em></div><div class="clock-status"><span>'+statusPill(br?'On Break':a?'Checked In':'Checked Out')+'</span><strong>'+hours.toFixed(2)+'h</strong><small>Worked today • '+weeklyHours(session.id).toFixed(2)+'h rolling seven days</small></div><div class="clock-actions">'+(!a?'<button class="btn primary clock-button" onclick="clockInNow()">▶ Check In</button>':br?'<button class="btn primary clock-button" onclick="breakInNow()">↩ Check Back In</button><button class="btn danger clock-button" onclick="clockOutNow()">■ Clock Out</button>':'<button class="btn secondary clock-button" onclick="breakOutNow()">☕ Break Out</button><button class="btn danger clock-button" onclick="clockOutNow()">■ Clock Out</button>')+'</div></div><div class="gps-disclosure">GPS is captured only when the browser grants location permission. Current Chrome/Edge/Firefox/Safari normally require HTTPS or localhost for geolocation. Attendance remains timestamped if location permission is denied.</div>'; }

function attendancePeriodBounds(period,ref){
 var d=ref?new Date(ref):new Date(),start=new Date(d),end=new Date(d);
 start.setHours(0,0,0,0);end.setHours(23,59,59,999);
 if(period==='Weekly'){var day=(start.getDay()+6)%7;start.setDate(start.getDate()-day);end=new Date(start);end.setDate(start.getDate()+6);end.setHours(23,59,59,999);}
 else if(period==='Monthly'){start=new Date(d.getFullYear(),d.getMonth(),1);end=new Date(d.getFullYear(),d.getMonth()+1,0,23,59,59,999);}
 else if(period==='Yearly'){start=new Date(d.getFullYear(),0,1);end=new Date(d.getFullYear(),11,31,23,59,59,999);}
 return {start:start,end:end};
}
function attendancePeriodKey(period,ref){
 var b=attendancePeriodBounds(period,ref),d=b.start;
 if(period==='Daily')return d.toISOString().slice(0,10);
 if(period==='Weekly')return d.toISOString().slice(0,10);
 if(period==='Monthly')return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
 return String(d.getFullYear());
}
function attendancePeriodLabel(period,ref){
 var b=attendancePeriodBounds(period,ref);
 if(period==='Daily')return b.start.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});
 if(period==='Weekly')return 'Week of '+b.start.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})+' – '+b.end.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});
 if(period==='Monthly')return b.start.toLocaleDateString(undefined,{month:'long',year:'numeric'});
 return String(b.start.getFullYear());
}
function timeEntryWithin(t,b){var d=new Date(t.clockIn);return d>=b.start&&d<=b.end;}
function uniqueAttendanceDays(rows){var m={};rows.forEach(function(t){m[new Date(t.clockIn).toISOString().slice(0,10)]=1;});return Object.keys(m).length;}
function buildAttendanceSummary(userId,period,ref){
 var b=attendancePeriodBounds(period,ref),rows=db.timeEntries.filter(function(t){return t.userId===userId&&timeEntryWithin(t,b);}),u=userById(userId),o=u&&orgById(u.orgId);
 var worked=rows.reduce(function(a,t){return a+workHours(t);},0),br=rows.reduce(function(a,t){return a+breakHours(t);},0);
 return {id:'attendance:'+userId+':'+period.toLowerCase()+':'+attendancePeriodKey(period,ref),userId:userId,orgId:u&&u.orgId||'',period:period,periodKey:attendancePeriodKey(period,ref),periodLabel:attendancePeriodLabel(period,ref),employeeName:u&&u.name||'',position:positionTitle(u),organization:o&&o.name||'',country:o&&o.country||'',shifts:rows.length,attendanceDays:uniqueAttendanceDays(rows),workedHours:Number(worked.toFixed(2)),breakHours:Number(br.toFixed(2)),openShifts:rows.filter(function(t){return !t.clockOut;}).length,generatedAt:nowISO()};
}
function refreshAutomaticAttendanceReports(){
 db.attendanceReports=db.attendanceReports||[];
 var periods=['Daily','Weekly','Monthly','Yearly'],users={};
 db.timeEntries.forEach(function(t){users[t.userId]=1;});
 if(session&&isClockUser())users[session.id]=1;
 Object.keys(users).forEach(function(uid){periods.forEach(function(period){var r=buildAttendanceSummary(uid,period,new Date()),i=db.attendanceReports.findIndex(function(x){return x.id===r.id;});if(i>=0)db.attendanceReports[i]=Object.assign(db.attendanceReports[i],r);else db.attendanceReports.unshift(r);});});
 save();
 return db.attendanceReports;
}
function currentAttendanceReport(period,userId){refreshAutomaticAttendanceReports();var id='attendance:'+(userId||session.id)+':'+period.toLowerCase()+':'+attendancePeriodKey(period,new Date());return db.attendanceReports.find(function(x){return x.id===id;})||buildAttendanceSummary(userId||session.id,period,new Date());}
function attendanceReportCards(){
 return '<div class="attendance-report-grid">'+['Daily','Weekly','Monthly','Yearly'].map(function(period){var r=currentAttendanceReport(period,session.id);return '<article class="card attendance-report-card"><span>'+esc(period.toUpperCase())+' ATTENDANCE REPORT</span><h4>'+esc(r.periodLabel)+'</h4><div class="attendance-report-kpis"><div><b>'+r.attendanceDays+'</b><small>Attendance days</small></div><div><b>'+r.shifts+'</b><small>Time entries</small></div><div><b>'+r.workedHours.toFixed(2)+'h</b><small>Worked</small></div><div><b>'+r.breakHours.toFixed(2)+'h</b><small>Breaks</small></div></div><div class="doc-actions"><button class="btn small" onclick="viewAttendanceReport(\''+period+'\')">View</button><button class="btn small primary" onclick="downloadAttendanceExcel(\''+period+'\',\'self\')">Download Excel</button></div></article>';}).join('')+'</div>';
}
function attendanceRowsForExport(period,scope){
 var b=attendancePeriodBounds(period,new Date()),allowedIds={};
 if(scope==='team'&&(isHighAdmin()||positionFamily()==='global_management'||session.positionId==='country-director'||session.positionId==='country-hr-volunteer-coordinator'))visibleTeamTime().forEach(function(t){allowedIds[t.userId]=1;});
 else allowedIds[session.id]=1;
 return db.timeEntries.filter(function(t){return allowedIds[t.userId]&&timeEntryWithin(t,b);}).sort(function(a,b){return String(a.clockIn).localeCompare(String(b.clockIn));});
}
function attendanceExcelPayload(period,scope){
 var rows=attendanceRowsForExport(period,scope),detail=[],breaks=[];
 rows.forEach(function(t){var u=userById(t.userId),o=orgById(t.orgId),bs=t.breaks||[];detail.push({employee:u&&u.name||'',position:positionTitle(u),organization:o&&o.name||'',country:o&&o.country||'',day:new Date(t.clockIn).toLocaleDateString(undefined,{weekday:'long'}),date:new Date(t.clockIn).toISOString().slice(0,10),month:new Date(t.clockIn).toLocaleDateString(undefined,{month:'long',year:'numeric'}),week:weekLabel(t.clockIn).replace('Week: ',''),checkIn:t.clockIn,clockOut:t.clockOut||'',breakHours:Number(breakHours(t).toFixed(2)),workedHours:Number(workHours(t).toFixed(2)),status:t.clockOut?'Complete':activeBreak(t)?'On Break':'Active',checkInLat:t.clockInLocation&&t.clockInLocation.lat,checkInLng:t.clockInLocation&&t.clockInLocation.lng,clockOutLat:t.clockOutLocation&&t.clockOutLocation.lat,clockOutLng:t.clockOutLocation&&t.clockOutLocation.lng,notes:t.notes||''});bs.forEach(function(br,i){breaks.push({employee:u&&u.name||'',date:new Date(t.clockIn).toISOString().slice(0,10),breakNo:i+1,breakOut:br.out||'',breakIn:br.in||'',durationHours:br.out&&br.in?Number(hoursBetween(br.out,br.in).toFixed(2)):0,outLat:br.outLocation&&br.outLocation.lat,outLng:br.outLocation&&br.outLocation.lng,inLat:br.inLocation&&br.inLocation.lat,inLng:br.inLocation&&br.inLocation.lng});});});
 var reports=['Daily','Weekly','Monthly','Yearly'].map(function(p){return currentAttendanceReport(p,session.id);});
 return {title:'Tech4Future-Global Time Clock & Attendance',period:period,periodLabel:attendancePeriodLabel(period,new Date()),scope:scope,generatedAt:nowISO(),generatedBy:session.name,organization:orgById(session.orgId)&&orgById(session.orgId).name||'',employee:scope==='self'?session.name:'Authorized Team',detail:detail,breaks:breaks,summary:reports};
}
function attendanceBrowserExcelFile(payload){
 var detailRows=payload.detail.map(function(r){return '<tr>'+[r.employee,r.position,r.organization,r.country,r.day,r.date,r.month,r.week,r.checkIn?new Date(r.checkIn).toLocaleTimeString():'',r.clockOut?new Date(r.clockOut).toLocaleTimeString():'',r.breakHours,r.workedHours,r.status,(r.checkInLat!=null?r.checkInLat+', '+r.checkInLng:''),(r.clockOutLat!=null?r.clockOutLat+', '+r.clockOutLng:''),r.notes].map(function(x){return '<td>'+esc(x==null?'':x)+'</td>';}).join('')+'</tr>';}).join('');
 var html='<html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#000}h1{background:#063f84;color:#fff;padding:18px}h2{color:#063f84}table{border-collapse:collapse;width:100%}th{background:#0a5aa6;color:#fff;padding:8px;border:1px solid #b8c7d8}td{padding:7px;border:1px solid #d7e0ea}tr:nth-child(even){background:#f4f8fc}</style></head><body><h1>'+esc(payload.title)+'</h1><p><b>Period:</b> '+esc(payload.periodLabel)+'<br><b>Employee/Scope:</b> '+esc(payload.employee)+'<br><b>Generated:</b> '+esc(longDateTime(payload.generatedAt))+'</p><h2>Attendance Detail</h2><table><tr>'+['Employee','Position','Organization','Country','Day','Date','Month','Week','Check In','Clock Out','Break Hours','Worked Hours','Status','Check-In GPS','Clock-Out GPS','Notes'].map(function(x){return '<th>'+x+'</th>';}).join('')+'</tr>'+detailRows+'</table></body></html>';
 return new File([html],'Tech4Future-Global_Attendance_'+periodFileName(payload.period)+'_'+new Date().toISOString().slice(0,10)+'.xls',{type:'application/vnd.ms-excel'});
}
function periodFileName(period){return String(period||'Attendance').replace(/\s+/g,'_');}
async function downloadAttendanceExcel(period,scope){
 var payload=attendanceExcelPayload(period||'Monthly',scope||'self');toast('Preparing Excel attendance report…');
 try{var res=await fetch('/api/exports/attendance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(res.ok){var j=await res.json(),a=document.createElement('a');a.href=j.downloadUrl;a.download=j.fileName;document.body.appendChild(a);a.click();a.remove();logAction('Downloaded attendance Excel report',payload.period+' • '+payload.scope);toast('Excel attendance workbook generated.');return;}}catch(e){}
 var file=attendanceBrowserExcelFile(payload);downloadBlob(file,file.name);logAction('Downloaded attendance Excel fallback',payload.period+' • '+payload.scope);toast('Excel-compatible attendance file generated in standalone mode.');
}
