function visibleFinanceRecords(){var ids=financeVisibleOrgIds(),rows=db.financeRecords.filter(function(r){return ids.indexOf(r.orgId)>=0;});if(!crossCountryFinanceRead()&&isProjectTeam()&&!canCreateFinance()){var ps=visibleProjects().map(function(p){return p.id;});rows=rows.filter(function(r){return ps.indexOf(r.projectId)>=0;});}return rows.sort(function(a,b){return String(b.date||b.createdAt).localeCompare(String(a.date||a.createdAt));});}
function renderFinance(){if(!canSeeFinance())return pageHeader('FINANCE CONTROL','Access Denied','Your position does not have financial visibility.');var rows=visibleFinanceRecords(),total=rows.filter(function(r){return ['expenditure','disbursement','petty_cash','payroll','transaction','expense_claim','cash_liquidation'].indexOf(r.type)>=0;}).reduce(function(a,r){return a+Number(r.amount||0);},0);return pageHeader('GLOBAL FINANCE & FIDUCIARY CONTROL','Financial Management Center','Active financial workplace for invoices, quotations, payment vouchers, procurement requests, purchase orders, payroll, advances, liquidations, disbursements, petty cash, reimbursements, expenditures, receipts, reconciliations and bookkeeping. Templates use donor/global-control fields and position-based segregation of duties.',canCreateFinance()?'<button class="btn primary" onclick="openFinanceMenu()">＋ New Financial Record</button>':'')+'<div class="kpis">'+kpi('VISIBLE RECORDS',String(rows.length),'Controlled finance scope')+kpi('RECORDED OUTFLOWS',money(total),'Based on visible records')+kpi('POSTED TO LEDGER',String(rows.filter(function(r){return r.status==='Posted';}).length),'Double-entry bookkeeping')+kpi('FINANCE ACCESS',crossCountryFinanceRead()?'Cross-country read':'Restricted scope','Position controlled')+'</div><div class="finance-standard-strip"><span>Delegated Authority</span><span>Segregation of Duties</span><span>Budget Availability</span><span>Donor / Award Coding</span><span>Procurement Reference</span><span>Tax / Withholding</span><span>Evidence Checklist</span><span>Audit Trail</span></div>'+sectionHead('FINANCIAL REGISTER','Transactions & source documents','Global Board and Advisory access is oversight/read-only; authorized finance users create/edit/post within approved scope.')+'<div class="card panel">'+financeTable(rows)+'</div>';}
function financeTable(rows){if(!rows.length)return '<div class="empty"><b>No finance records yet</b>Authorized financial employees can create the first invoice, quotation, payroll, disbursement, petty cash, expenditure, receipt or transaction.</div>';return '<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Type</th><th>Organization</th><th>Date</th><th>Counterparty</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+rows.map(function(r){return '<tr><td><b>'+esc(r.reference)+'</b></td><td>'+esc(FINANCE_TYPE_LABELS[r.type]||r.type)+'</td><td>'+esc(orgById(r.orgId)&&orgById(r.orgId).name||'')+'</td><td>'+esc(r.date||'')+'</td><td>'+esc(r.party||'')+'</td><td><b>'+money(r.amount)+'</b></td><td>'+statusPill(r.status||'Draft')+'</td><td><div class="doc-actions"><button class="btn small" onclick="viewFinanceRecord(\''+r.id+'\')">View</button>'+(canEditFinanceRecord(r)?'<button class="btn small secondary" onclick="openFinanceRecordModal(\''+r.type+'\',\''+r.id+'\')">Edit</button><button class="btn small danger" onclick="deleteFinanceRecord(\''+r.id+'\')">Delete</button>':'')+'<button class="btn small" onclick="downloadFinanceRecord(\''+r.id+'\')">Download</button><button class="btn small" onclick="printFinanceRecord(\''+r.id+'\')">Print</button></div></td></tr>';}).join('')+'</tbody></table></div>';}
function openFinanceMenu(){if(!canCreateFinance()){toast('Financial record creation is restricted to authorized financial employees.');return;}showModal('FINANCE','Create financial record','<div class="finance-type-grid">'+FINANCE_TYPES.map(function(t){return '<button class="finance-type-card" onclick="closeModal();openFinanceRecordModal(\''+t[0]+'\')"><span>$</span><b>'+esc(t[1])+'</b><small>Create / generate record</small></button>';}).join('')+'</div>');}
function financeOrgOptions(selected){var orgs;if(isPlatformAdmin()||GLOBAL_FINANCE_POSITIONS.indexOf(session.positionId)>=0||REGIONAL_FINANCE_POSITIONS.indexOf(session.positionId)>=0)orgs=db.organizations.filter(function(o){return o.id==='t4f-hq'||o.type==='country_office';});else orgs=db.organizations.filter(function(o){return o.id===session.orgId;});return orgs.map(function(o){return '<option value="'+o.id+'" '+(o.id===selected?'selected':'')+'>'+esc(o.name)+'</option>';}).join('');}
function openFinanceRecordModal(type,id){if(id){var existing=db.financeRecords.find(function(x){return x.id===id;});if(!canEditFinanceRecord(existing)){toast('Read-only financial access.');return;}}else if(!canCreateFinance()){toast('Your position cannot create financial transactions.');return;}var r=id?db.financeRecords.find(function(x){return x.id===id;}):{type:type,orgId:session.orgId,reference:(type||'FIN').toUpperCase().replace(/_/g,'').slice(0,5)+'-'+Date.now().toString().slice(-8),date:new Date().toISOString().slice(0,10),party:'',description:'',amount:'',currency:'USD',status:'Draft',projectId:'',budgetId:'',fundingSource:'',awardId:'',costCenter:'',accountCode:'',procurementRef:'',paymentMethod:'',paymentRef:'',taxWithholding:'',debitAccount:'',creditAccount:'',lineItems:'',evidenceChecklist:'',preparedBy:session.name,reviewNotes:''};var statusOptions=['Draft','Pending Approval','Pre-Approved'];if(canApproveFinance())statusOptions.push('Approved');if(canPostFinance())statusOptions.push('Posted','Paid');if(canApproveFinance())statusOptions.push('Void');if(statusOptions.indexOf(r.status)<0)statusOptions.push(r.status);showModal('FINANCIAL MANAGEMENT',id?'Edit '+FINANCE_TYPE_LABELS[r.type]:'New '+FINANCE_TYPE_LABELS[type],'<form id="financeForm" class="form-grid finance-form"><label>Organization<select id="finOrg">'+financeOrgOptions(r.orgId)+'</select></label><label>Reference<input id="finRef" value="'+esc(r.reference)+'" required></label><label>Date<input id="finDate" type="date" value="'+esc(r.date)+'" required></label><label>Transaction / document type<input value="'+esc(FINANCE_TYPE_LABELS[r.type]||r.type)+'" disabled></label><label>Counterparty / Employee / Vendor<input id="finParty" value="'+esc(r.party||'')+'"></label><label>Amount<input id="finAmount" type="number" min="0" step="0.01" value="'+esc(r.amount||'')+'" required></label><label>Currency<input id="finCurrency" value="'+esc(r.currency||'USD')+'"></label><label>Status<select id="finStatus">'+statusOptions.map(function(x){return '<option>'+x+'</option>';}).join('')+'</select></label><label>Project / Programme<select id="finProject"><option value="">None</option>'+db.projects.map(function(p){return '<option value="'+p.id+'" '+(p.id===r.projectId?'selected':'')+'>'+esc(p.projectCode||'')+' — '+esc(p.name)+'</option>';}).join('')+'</select></label><label>Budget<select id="finBudget"><option value="">None</option>'+db.budgets.map(function(b){return '<option value="'+b.id+'" '+(b.id===r.budgetId?'selected':'')+'>'+esc(b.title)+'</option>';}).join('')+'</select></label><label>Funding source / Donor<input id="finFunding" value="'+esc(r.fundingSource||'')+'"></label><label>Award / Grant ID<input id="finAward" value="'+esc(r.awardId||'')+'"></label><label>Cost center / Country code<input id="finCostCenter" value="'+esc(r.costCenter||'')+'"></label><label>Account / Chart code<input id="finAccountCode" value="'+esc(r.accountCode||'')+'"></label><label>Procurement / PO reference<input id="finProcRef" value="'+esc(r.procurementRef||'')+'"></label><label>Payment method<input id="finPaymentMethod" value="'+esc(r.paymentMethod||'')+'" placeholder="Bank / ACH / cheque / mobile money / cash"></label><label>Payment / bank reference<input id="finPaymentRef" value="'+esc(r.paymentRef||'')+'"></label><label>Tax / withholding<input id="finTax" value="'+esc(r.taxWithholding||'')+'"></label><label>Debit account<input id="finDebit" value="'+esc(r.debitAccount||'')+'" placeholder="Expense / Asset / Receivable"></label><label>Credit account<input id="finCredit" value="'+esc(r.creditAccount||'')+'" placeholder="Cash / Payable / Income"></label><label class="full">Purpose / business justification<textarea id="finDesc" rows="3">'+esc(r.description||'')+'</textarea></label><label class="full">Line items / payroll / quotation detail<textarea id="finLines" rows="5" placeholder="Item | Description | Qty | Unit | Rate | Amount | Account / budget line">'+esc(r.lineItems||'')+'</textarea></label><label class="full">Supporting evidence checklist<textarea id="finEvidence" rows="3" placeholder="Approved requisition; quotation(s); PO/contract; invoice; receipt; attendance/timesheet; delivery evidence; tax support; donor eligibility…">'+esc(r.evidenceChecklist||'')+'</textarea></label><label class="full">Review / approval notes<textarea id="finReview" rows="3">'+esc(r.reviewNotes||'')+'</textarea></label><div class="credential-box full"><b>Financial control gates:</b> delegated authority • budget availability • segregation of duties • donor/award allowability • procurement evidence • tax/withholding • payment evidence • reconciliation • record retention. These are Tech4Future-Global controls informed by global/UN financial-management practice; they do not replace the organization’s adopted policies or applicable law.</div><div class="form-actions"><button type="button" class="btn secondary" onclick="openAIAssistant(\'finance\')">AI Narrative Assistant</button><button class="btn primary">Save '+esc(FINANCE_TYPE_LABELS[r.type])+'</button></div></form>');$('#finStatus').value=r.status||'Draft';$('#financeForm').onsubmit=function(e){e.preventDefault();var obj=id?r:{id:uuid(),type:type,createdAt:nowISO(),createdBy:session.id};Object.assign(obj,{orgId:$('#finOrg').value,reference:$('#finRef').value.trim(),date:$('#finDate').value,party:$('#finParty').value.trim(),amount:Number($('#finAmount').value||0),currency:$('#finCurrency').value.trim()||'USD',status:$('#finStatus').value,projectId:$('#finProject').value,budgetId:$('#finBudget').value,fundingSource:$('#finFunding').value.trim(),awardId:$('#finAward').value.trim(),costCenter:$('#finCostCenter').value.trim(),accountCode:$('#finAccountCode').value.trim(),procurementRef:$('#finProcRef').value.trim(),paymentMethod:$('#finPaymentMethod').value.trim(),paymentRef:$('#finPaymentRef').value.trim(),taxWithholding:$('#finTax').value.trim(),debitAccount:$('#finDebit').value.trim(),creditAccount:$('#finCredit').value.trim(),description:$('#finDesc').value.trim(),lineItems:$('#finLines').value.trim(),evidenceChecklist:$('#finEvidence').value.trim(),reviewNotes:$('#finReview').value.trim(),updatedAt:nowISO(),updatedBy:session.id});if(!id)db.financeRecords.unshift(obj);syncLedgerFromFinance(obj);save();logAction(id?'Edited finance record':'Created finance record',obj.reference+' — '+FINANCE_TYPE_LABELS[obj.type],obj.orgId);closeModal();render('finance');toast('Financial record saved.');};}
function syncLedgerFromFinance(r){db.ledger=db.ledger.filter(function(l){return l.sourceFinanceId!==r.id;});if(r.status!=='Posted')return;var amt=Number(r.amount||0);if(!amt)return;db.ledger.push({id:uuid(),orgId:r.orgId,date:r.date,reference:r.reference,description:r.description||FINANCE_TYPE_LABELS[r.type],account:r.debitAccount||'Unclassified Debit',debit:amt,credit:0,sourceFinanceId:r.id,createdAt:nowISO()});db.ledger.push({id:uuid(),orgId:r.orgId,date:r.date,reference:r.reference,description:r.description||FINANCE_TYPE_LABELS[r.type],account:r.creditAccount||'Unclassified Credit',debit:0,credit:amt,sourceFinanceId:r.id,createdAt:nowISO()});}
function viewFinanceRecord(id){var r=db.financeRecords.find(function(x){return x.id===id;});if(!r)return;showModal('FINANCIAL RECORD',FINANCE_TYPE_LABELS[r.type],financeRecordHtml(r)+'<div class="form-actions" style="padding:0 21px 21px"><button class="btn" onclick="downloadFinanceRecord(\''+r.id+'\')">Download</button><button class="btn primary" onclick="printFinanceRecord(\''+r.id+'\')">Print</button></div>');}
function financeRecordHtml(r){return '<div class="document-preview"><div class="doc-preview-head"><div><span>TECH4FUTURE-GLOBAL</span><h3>'+esc(FINANCE_TYPE_LABELS[r.type])+'</h3></div><b>'+esc(r.reference)+'</b></div><div class="info-grid"><div class="info-item"><span>Organization</span><b>'+esc(orgById(r.orgId)&&orgById(r.orgId).name||'')+'</b></div><div class="info-item"><span>Date</span><b>'+esc(r.date)+'</b></div><div class="info-item"><span>Counterparty</span><b>'+esc(r.party||'—')+'</b></div><div class="info-item"><span>Status</span><b>'+esc(r.status)+'</b></div></div><div class="finance-amount">'+money(r.amount)+'</div><div class="tor-section"><h4>Description / Purpose</h4><p>'+esc(r.description||'—')+'</p></div>'+(r.lineItems?'<div class="tor-section"><h4>Line Items / Details</h4><p style="white-space:pre-wrap">'+esc(r.lineItems)+'</p></div>':'')+'<div class="finance-coding"><span>Debit: '+esc(r.debitAccount||'—')+'</span><span>Credit: '+esc(r.creditAccount||'—')+'</span></div></div>';}
function downloadFinanceRecord(id){var r=db.financeRecords.find(function(x){return x.id===id;});if(!r)return;var csv='Field,Value\nType,"'+(FINANCE_TYPE_LABELS[r.type]||r.type).replace(/"/g,'""')+'"\nReference,"'+String(r.reference).replace(/"/g,'""')+'"\nOrganization,"'+String(orgById(r.orgId)&&orgById(r.orgId).name||'').replace(/"/g,'""')+'"\nDate,"'+r.date+'"\nCounterparty,"'+String(r.party||'').replace(/"/g,'""')+'"\nAmount,'+r.amount+'\nStatus,"'+r.status+'"\nDescription,"'+String(r.description||'').replace(/"/g,'""')+'"\nDebit Account,"'+String(r.debitAccount||'').replace(/"/g,'""')+'"\nCredit Account,"'+String(r.creditAccount||'').replace(/"/g,'""')+'"\nLine Items,"'+String(r.lineItems||'').replace(/"/g,'""')+'"\n';downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),slug(r.reference)+'-'+r.type+'.csv');logAction('Downloaded finance record',r.reference,r.orgId);}
function printFinanceRecord(id){var r=db.financeRecords.find(function(x){return x.id===id;});if(!r)return;printHtml(FINANCE_TYPE_LABELS[r.type]+' '+r.reference,financeRecordHtml(r));}

/* bookkeeping */
function visibleLedger(){var ids=financeVisibleOrgIds();return db.ledger.filter(function(l){return ids.indexOf(l.orgId)>=0;}).sort(function(a,b){return String(b.date).localeCompare(String(a.date));});}
function renderBookkeeping(){if(!canSeeBookkeeping())return pageHeader('BOOKKEEPING','Access Denied','Your position does not have general-ledger visibility.');var rows=visibleLedger(),debit=rows.reduce(function(a,x){return a+Number(x.debit||0);},0),credit=rows.reduce(function(a,x){return a+Number(x.credit||0);},0);return pageHeader('BOOKKEEPING','General Ledger & Bookkeeping','Posted financial records automatically create balanced debit/credit entries. Authorized finance staff can also enter controlled manual journals.',canCreateFinance()?'<button class="btn secondary" onclick="openJournalModal()">＋ Manual journal</button>':'')+'<div class="kpis">'+kpi('LEDGER LINES',String(rows.length),'Visible scope')+kpi('TOTAL DEBITS',money(debit),'Visible ledger')+kpi('TOTAL CREDITS',money(credit),'Visible ledger')+kpi('BALANCE',money(debit-credit),'Should reconcile to zero')+'</div>'+sectionHead('GENERAL LEDGER','Bookkeeping register','Country data follows the same finance visibility rules.')+'<div class="card panel">'+ledgerTable(rows)+'</div>';}
function ledgerTable(rows){if(!rows.length)return '<div class="empty"><b>No ledger entries</b>Post financial records or create a journal entry.</div>';return '<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Reference</th><th>Organization</th><th>Account</th><th>Description</th><th>Debit</th><th>Credit</th></tr></thead><tbody>'+rows.map(function(l){return '<tr><td>'+esc(l.date)+'</td><td><b>'+esc(l.reference)+'</b></td><td>'+esc(orgById(l.orgId)&&orgById(l.orgId).name||'')+'</td><td>'+esc(l.account)+'</td><td>'+esc(l.description||'')+'</td><td>'+money(l.debit)+'</td><td>'+money(l.credit)+'</td></tr>';}).join('')+'</tbody></table></div>';}
function openJournalModal(){if(!canCreateFinance())return;showModal('BOOKKEEPING','Manual journal entry','<form id="journalForm" class="form-grid"><label>Organization<select id="jOrg">'+financeOrgOptions(session.orgId)+'</select></label><label>Date<input id="jDate" type="date" value="'+new Date().toISOString().slice(0,10)+'"></label><label>Reference<input id="jRef" value="JRN-'+Date.now().toString().slice(-7)+'"></label><label>Debit account<input id="jDebitAcct" required></label><label>Credit account<input id="jCreditAcct" required></label><label>Amount<input id="jAmount" type="number" min="0" step="0.01" required></label><label class="full">Description<textarea id="jDesc" rows="3"></textarea></label><div class="form-actions"><button class="btn primary">Post journal</button></div></form>');$('#journalForm').onsubmit=function(e){e.preventDefault();var org=$('#jOrg').value,date=$('#jDate').value,ref=$('#jRef').value.trim(),amt=Number($('#jAmount').value||0),desc=$('#jDesc').value.trim();db.ledger.push({id:uuid(),orgId:org,date:date,reference:ref,description:desc,account:$('#jDebitAcct').value.trim(),debit:amt,credit:0,manual:true,createdBy:session.id,createdAt:nowISO()});db.ledger.push({id:uuid(),orgId:org,date:date,reference:ref,description:desc,account:$('#jCreditAcct').value.trim(),debit:0,credit:amt,manual:true,createdBy:session.id,createdAt:nowISO()});save();logAction('Posted manual journal',ref,org);closeModal();render('bookkeeping');};}

/* budgets */
function visibleBudgets(){var ids=financeVisibleOrgIds(),rows=db.budgets.filter(function(b){return ids.indexOf(b.orgId)>=0;});if(!crossCountryFinanceRead()&&isProjectTeam()&&!COUNTRY_FINANCE_POSITIONS.indexOf(session.positionId)>=0){var ps=visibleProjects().map(function(p){return p.id;});rows=rows.filter(function(b){return ps.indexOf(b.projectId)>=0||b.orgId===session.orgId;});}return rows.sort(function(a,b){return String(b.fiscalYear).localeCompare(String(a.fiscalYear));});}
function renderBudgets(){var rows=visibleBudgets();return pageHeader('BUDGET MANAGEMENT','Project, Program, Operational & Administrative Budgets','Develop and manage project, program, operational and administrative budgets with planned amounts, approved amounts, actual spend and variance.',canCreateFinance()||isProjectHead()?'<button class="btn secondary" onclick="openBudgetModal()">＋ New budget</button>':'')+'<div class="budget-grid">'+(rows.length?rows.map(budgetCard).join(''):'<div class="card empty"><b>No budgets yet</b>Create project, program, operational or administrative budgets.</div>')+'</div>';}
function budgetCard(b){var actual=budgetActual(b),variance=Number(b.plannedAmount||0)-actual;return '<div class="card budget-card"><div class="budget-head"><div><span class="eyebrow">'+esc(b.type.toUpperCase())+'</span><h4>'+esc(b.title)+'</h4><p>'+esc(orgById(b.orgId)&&orgById(b.orgId).name||'')+' • FY '+esc(b.fiscalYear)+'</p></div>'+statusPill(b.status||'Draft')+'</div><div class="budget-stats"><div><span>Planned</span><b>'+money(b.plannedAmount)+'</b></div><div><span>Approved</span><b>'+money(b.approvedAmount)+'</b></div><div><span>Actual</span><b>'+money(actual)+'</b></div><div><span>Variance</span><b>'+money(variance)+'</b></div></div><div class="progress"><i style="width:'+Math.min(100,b.plannedAmount?actual/Number(b.plannedAmount)*100:0)+'%"></i></div><div class="project-actions">'+(canEditBudget(b)?'<button class="btn small secondary" onclick="openBudgetModal(\''+b.id+'\')">Edit</button><button class="btn small danger" onclick="deleteBudget(\''+b.id+'\')">Delete</button>':'')+'<button class="btn small" onclick="printBudget(\''+b.id+'\')">Print</button></div></div>';}
function budgetActual(b){return db.financeRecords.filter(function(r){return r.budgetId===b.id&&['Approved','Posted','Paid'].indexOf(r.status)>=0&&['expenditure','disbursement','petty_cash','payroll','transaction'].indexOf(r.type)>=0;}).reduce(function(a,r){return a+Number(r.amount||0);},0);}
function openBudgetModal(id,projectId){var b=id?db.budgets.find(function(x){return x.id===id;}):{orgId:session.orgId,title:'',type:projectId?'Project':'Operational',projectId:projectId||'',fiscalYear:String(new Date().getFullYear()),plannedAmount:'',approvedAmount:'',status:'Draft',lineItems:''};if(id&&!canEditBudget(b)){toast('Read-only budget access.');return;}var allowNew=canCreateFinance()||isProjectHead();if(!id&&!allowNew){toast('Your position cannot create budgets.');return;}showModal('BUDGETING',id?'Edit budget':'Create budget','<form id="budgetForm" class="form-grid"><label>Organization<select id="bOrg">'+financeOrgOptions(b.orgId)+'</select></label><label>Budget type<select id="bType"><option>Project</option><option>Program</option><option>Operational</option><option>Administrative</option></select></label><label class="full">Budget title<input id="bTitle" value="'+esc(b.title)+'" required></label><label>Fiscal year<input id="bYear" value="'+esc(b.fiscalYear)+'" required></label><label>Project / Program<select id="bProject"><option value="">Organization-level</option>'+db.projects.map(function(p){return '<option value="'+p.id+'" '+(p.id===b.projectId?'selected':'')+'>'+esc(p.name)+'</option>';}).join('')+'</select></label><label>Planned amount<input id="bPlanned" type="number" min="0" step="0.01" value="'+esc(b.plannedAmount||'')+'"></label><label>Approved amount<input id="bApproved" type="number" min="0" step="0.01" value="'+esc(b.approvedAmount||'')+'"></label><label>Status<select id="bStatus"><option>Draft</option><option>Pending Approval</option><option>Approved</option><option>Closed</option></select></label><label class="full">Budget lines<textarea id="bLines" rows="7" placeholder="Personnel | 25000\nTraining Equipment | 18000\nTravel | 7000">'+esc(b.lineItems||'')+'</textarea></label><div class="form-actions"><button class="btn primary">Save budget</button></div></form>');$('#bType').value=b.type;$('#bStatus').value=b.status||'Draft';$('#budgetForm').onsubmit=function(e){e.preventDefault();var obj=id?b:{id:uuid(),createdAt:nowISO(),createdBy:session.id};Object.assign(obj,{orgId:$('#bOrg').value,type:$('#bType').value,title:$('#bTitle').value.trim(),fiscalYear:$('#bYear').value.trim(),projectId:$('#bProject').value,plannedAmount:Number($('#bPlanned').value||0),approvedAmount:Number($('#bApproved').value||0),status:$('#bStatus').value,lineItems:$('#bLines').value.trim(),updatedAt:nowISO()});if(!id)db.budgets.unshift(obj);save();logAction(id?'Updated budget':'Created budget',obj.title,obj.orgId);closeModal();render(currentPage==='project_workspace'?'project_workspace':'budgets');};}
function printBudget(id){var b=db.budgets.find(function(x){return x.id===id;});if(!b)return;printHtml('Budget — '+b.title,'<h1>'+esc(b.title)+'</h1><p><b>Type:</b> '+esc(b.type)+' &nbsp; <b>Fiscal Year:</b> '+esc(b.fiscalYear)+'</p><p><b>Organization:</b> '+esc(orgById(b.orgId)&&orgById(b.orgId).name||'')+'</p><h2>Planned: '+money(b.plannedAmount)+'</h2><h3>Approved: '+money(b.approvedAmount)+'</h3><hr><pre style="white-space:pre-wrap">'+esc(b.lineItems||'')+'</pre>');}


/* stakeholders/income */
function contributionRows(type){
 var rows=db.contributions.filter(function(c){return c.type===type;});
 if(isExternalUser()){var o=orgById(session.orgId);rows=rows.filter(function(c){return c.organizationId===o.id||String(c.organization||'').toLowerCase()===String(o.name||'').toLowerCase();});}
 return rows;
}
function renderStakeholderOverview(){
 var types=[['donor','Donor Organizations'],['regular_sponsor','Sponsors'],['supporter','Supporters'],['partner','Partners']];
 return pageHeader('STAKEHOLDERS','Stakeholders Dashboard','One consolidated stakeholder view for organization records, Fiscal Visibility income registers, approved reports and portal relationships.',canManageStakeholders()?'<button class="btn primary" onclick="openOrganizationModal(null,\'donor\')">＋ Add Stakeholder</button>':'')+
 '<div class="stakeholder-overview-grid">'+types.map(function(x){var orgCount=isExternalUser()?(orgById(session.orgId)&&orgById(session.orgId).type===x[0]?1:0):db.organizations.filter(function(o){return o.type===x[0];}).length;var income=contributionRows(x[0]);return '<div class="card stakeholder-summary"><span>'+esc(x[1].toUpperCase())+'</span><strong>'+orgCount+'</strong><small>Organization records</small><div class="stakeholder-income"><b>'+money(income.reduce(function(a,c){return a+Number(c.amount||0);},0))+'</b><em>'+income.length+' income record(s)</em></div><div class="doc-actions"><button class="btn small" onclick="go(\''+(x[0]==='donor'?'donors':x[0]==='regular_sponsor'?'sponsors':x[0]==='supporter'?'supporters':'partners')+'\')">Organizations</button><button class="btn small secondary" onclick="go(\''+(x[0]==='donor'?'donor_income':x[0]==='regular_sponsor'?'sponsor_income':x[0]==='supporter'?'supporter_income':'partner_income')+'\')">Income</button></div></div>';}).join('')+'</div>'+
 sectionHead('FISCAL VISIBILITY','Income registers under Stakeholders','Donor Income • Sponsor Income • Supporter Income • Partner Income')+
 '<div class="income-strip">'+types.map(function(x){return '<button class="income-strip-card" onclick="go(\''+(x[0]==='donor'?'donor_income':x[0]==='regular_sponsor'?'sponsor_income':x[0]==='supporter'?'supporter_income':'partner_income')+'\')"><span>'+esc(x[1])+'</span><b>'+money(contributionRows(x[0]).reduce(function(a,c){return a+Number(c.amount||0);},0))+'</b><small>'+contributionRows(x[0]).length+' records</small></button>';}).join('')+'</div>';
}
function renderStakeholders(type){
 var map={donor:'Donor Organizations',regular_sponsor:'Sponsors',supporter:'Supporters',partner:'Partners'},
 rows=db.organizations.filter(function(o){return o.type===type;});
 if(isExternalUser())rows=rows.filter(function(o){return o.id===session.orgId;});
 var incomes=contributionRows(type);
 return pageHeader('STAKEHOLDERS',map[type],'Created and imported stakeholder records appear here together with the matching Fiscal Visibility income register.',canManageStakeholders()?'<button class="btn primary" onclick="openOrganizationModal(null,\''+type+'\')">＋ Add '+esc(map[type].replace(' Organizations','').replace(/s$/,''))+'</button><button class="btn secondary" onclick="openStakeholderImport(\''+type+'\')">Upload CSV</button>':'')+
 '<div class="kpis">'+kpi('ORGANIZATIONS',String(rows.length),'Current records')+kpi('INCOME TOTAL',money(incomes.reduce(function(a,c){return a+Number(c.amount||0);},0)),'Fiscal Visibility')+kpi('INCOME RECORDS',String(incomes.length),'Matching transactions')+kpi('REPORTS',String(visibleReports().length),'Visible reports')+'</div>'+
 '<div class="card panel">'+organizationTable(rows)+'</div>'+
 sectionHead('FISCAL VISIBILITY',map[type].replace(' Organizations','')+' Income','Income records created or uploaded for this stakeholder category.')+
 '<div class="card panel">'+incomeTable(type,incomes)+'</div>';
}
function sumIncome(type){return db.contributions.filter(function(c){return c.type===type;}).reduce(function(a,c){return a+Number(c.amount||0);},0);}
function incomeTable(type,rows){
 rows=rows||contributionRows(type);
 if(!rows.length)return '<div class="empty"><b>No income records yet</b>Create or upload the first record when authorized.</div>';
 return '<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Organization</th><th>Reference</th><th>Amount</th><th>Purpose</th><th>Supporting File</th></tr></thead><tbody>'+
 rows.map(function(c){return '<tr><td>'+esc(c.date||'')+'</td><td>'+esc(c.organization||orgById(c.organizationId)&&orgById(c.organizationId).name||'')+'</td><td>'+esc(c.reference||'—')+'</td><td><b>'+money(c.amount)+'</b></td><td>'+esc(c.purpose||'')+'</td><td>'+(c.fileName?'<button class="btn small" onclick="downloadIncomeFile(\''+c.id+'\')">'+esc(c.fileName)+'</button>':'—')+'</td></tr>';}).join('')+'</tbody></table></div>';
}
function renderIncome(type){
 var labels={donor:'Donor',regular_sponsor:'Sponsor',supporter:'Supporter',partner:'Partner'},rows=contributionRows(type),total=rows.reduce(function(a,c){return a+Number(c.amount||0);},0);
 return pageHeader('STAKEHOLDERS • FISCAL VISIBILITY',labels[type]+' Income','Authorized income register linked directly to the Stakeholders Dashboard and the '+labels[type]+' organization dashboard.',canManageIncome()?'<button class="btn primary" onclick="openIncomeRecordModal(\''+type+'\')">＋ Create Income Record</button><button class="btn secondary" onclick="openIncomeImport(\''+type+'\')">Upload CSV</button>':'')+
 '<div class="kpis">'+kpi('TOTAL',money(total),'Recorded contributions')+kpi('RECORDS',String(rows.length),'Income records')+kpi('STAKEHOLDER REPORTS',String(visibleReports().length),'Visible reporting')+kpi('CATEGORY',labels[type],'Fiscal Visibility')+'</div>'+
 '<div class="card panel" style="margin-top:17px">'+incomeTable(type,rows)+'</div>';
}
function openIncomeRecordModal(type){
 if(!canManageIncome()){toast('You do not have income-record creation authority.');return;}
 var orgs=db.organizations.filter(function(o){return o.type===type;});
 showModal('FISCAL VISIBILITY','Create '+({donor:'Donor',regular_sponsor:'Sponsor',supporter:'Supporter',partner:'Partner'}[type])+' Income Record','<form id="incomeForm" class="form-grid"><label>Stakeholder Organization<select id="incomeOrg">'+orgs.map(function(o){return '<option value="'+o.id+'">'+esc(o.name)+'</option>';}).join('')+'</select></label><label>Date<input id="incomeDate" type="date" value="'+new Date().toISOString().slice(0,10)+'"></label><label>Amount<input id="incomeAmount" type="number" min="0" step="0.01" required></label><label>Reference / Receipt No.<input id="incomeReference"></label><label class="full">Purpose / restriction / funding note<textarea id="incomePurpose" rows="4"></textarea></label><label class="full">Supporting file / receipt<input id="incomeFile" type="file"></label><div class="form-actions"><button class="btn primary">Save Income Record</button></div></form>');
 $('#incomeForm').onsubmit=async function(e){e.preventDefault();var oid=$('#incomeOrg').value,o=orgById(oid),r={id:uuid(),type:type,organizationId:oid,organization:o&&o.name||'',date:$('#incomeDate').value,amount:Number($('#incomeAmount').value||0),reference:$('#incomeReference').value.trim(),purpose:$('#incomePurpose').value.trim(),fileName:'',createdAt:nowISO(),createdBy:session.id};var f=$('#incomeFile').files[0];if(f){await putBlob('incomeFiles',r.id,f);r.fileName=f.name;}db.contributions.unshift(r);save();logAction('Created stakeholder income record',r.organization+' — '+money(r.amount),oid);closeModal();render(currentPage);toast('Income record saved and now appears on the stakeholder and income dashboards.');};
}
async function downloadIncomeFile(id){var c=db.contributions.find(function(x){return x.id===id;});if(!c||!c.fileName)return;var blob=await getBlob('incomeFiles',id);if(!blob){toast('Supporting file is not available in this browser.');return;}downloadBlob(blob.blob||blob,c.fileName||blob.name);}
function parseSimpleCSV(text){var lines=String(text||'').split(/\\r?\\n/).filter(function(x){return x.trim();});if(!lines.length)return[];function split(line){var out=[],cur='',q=false;for(var i=0;i<line.length;i++){var ch=line[i];if(ch==='\"'){if(q&&line[i+1]==='\"'){cur+='\"';i++;}else q=!q;}else if(ch===','&&!q){out.push(cur.trim());cur='';}else cur+=ch;}out.push(cur.trim());return out;}var headers=split(lines[0]).map(function(h){return h.toLowerCase().trim();});return lines.slice(1).map(function(line){var v=split(line),o={};headers.forEach(function(h,i){o[h]=v[i]||'';});return o;});}
function openStakeholderImport(type){
 if(!canManageStakeholders())return;
 showModal('STAKEHOLDER IMPORT','Upload '+({donor:'Donor Organizations',regular_sponsor:'Sponsors',supporter:'Supporters',partner:'Partners'}[type])+' CSV','<form id="stakeImportForm" class="form-grid"><div class="credential-box full">CSV columns: <b>name, country, contact_name, email, phone, status</b>. Imported records immediately appear on this dashboard and the Organizations dashboard.</div><label class="full">CSV file<input id="stakeImportFile" type="file" accept=".csv,text/csv" required></label><div class="form-actions"><button class="btn primary">Import Stakeholders</button></div></form>');
 $('#stakeImportForm').onsubmit=async function(e){e.preventDefault();var f=$('#stakeImportFile').files[0],rows=parseSimpleCSV(await f.text()),n=0;rows.forEach(function(r){if(!r.name)return;var id='org-'+slug(r.name)+'-'+Date.now().toString().slice(-5)+'-'+n;db.organizations.push({id:id,name:r.name,type:type,country:r.country||'',parentId:null,status:r.status||'Active',contact:{name:r.contact_name||'',email:(r.email||'').toLowerCase(),phone:r.phone||'',address:'',fax:'',bio:''}});n++;});save();logAction('Imported stakeholder organizations',String(n)+' '+type+' records','t4f-hq');closeModal();render(currentPage);toast(n+' stakeholder record(s) imported.');};
}
function openIncomeImport(type){
 if(!canManageIncome())return;
 showModal('FISCAL VISIBILITY','Upload Income CSV','<form id="incomeImportForm" class="form-grid"><div class="credential-box full">CSV columns: <b>date, organization, amount, purpose, reference</b>. Organization names should match an existing stakeholder organization in this category.</div><label class="full">CSV file<input id="incomeImportFile" type="file" accept=".csv,text/csv" required></label><div class="form-actions"><button class="btn primary">Import Income Records</button></div></form>');
 $('#incomeImportForm').onsubmit=async function(e){e.preventDefault();var f=$('#incomeImportFile').files[0],rows=parseSimpleCSV(await f.text()),n=0;rows.forEach(function(r){if(!r.organization&&!r.amount)return;var o=db.organizations.find(function(x){return x.type===type&&String(x.name).toLowerCase()===String(r.organization||'').toLowerCase();});db.contributions.unshift({id:uuid(),type:type,organizationId:o&&o.id||'',organization:r.organization||o&&o.name||'',date:r.date||new Date().toISOString().slice(0,10),amount:Number(r.amount||0),purpose:r.purpose||'',reference:r.reference||'',fileName:'',createdAt:nowISO(),createdBy:session.id});n++;});save();logAction('Imported stakeholder income',String(n)+' '+type+' records','t4f-hq');closeModal();render(currentPage);toast(n+' income record(s) imported.');};
}

function advanceReport(id,status){var r=db.reports.find(function(x){return x.id===id;});if(!r)return;if(status==='Pre-Approved'&&!canReviewReport(r)){toast('You do not have report pre-approval authority.');return;}if(status==='Approved'&&!canApproveReport(r)){toast('You do not have report approval authority.');return;}r.workflowStatus=status;r.status=status;db.reportReviews=db.reportReviews||[];db.reportReviews.unshift({id:uuid(),reportId:id,userId:session.id,reviewer:session.name,position:positionTitle(),status:status,createdAt:nowISO()});save();logAction('Advanced report workflow',r.title+' → '+status,r.orgId);render('reports');}


function renderAI(){var history=(db.aiHistory||[]).filter(function(h){return h.userId===session.id;}).slice(0,20),files=(db.aiFiles||[]).filter(function(f){return f.userId===session.id;}).slice(0,30);return pageHeader('AI & KNOWLEDGE','AI Assistance Center','Active drafting workspace with secure server AI when configured, automatic working-file preservation, and Word/Excel export. Narrative documents default to Word; finance, budget, data and table-oriented outputs default to Excel.','<button class="btn primary" onclick="openAIAssistant(\'general\')">✦ Start AI Assistance</button>')+'<div class="ai-grid">'+AI_PROVIDERS.map(function(p){return '<div class="card ai-card"><div class="ai-provider-icon">'+esc(p.name.slice(0,2).toUpperCase())+'</div><h4>'+esc(p.name)+'</h4><p>'+esc(p.use)+'</p><span class="status '+(p.id==='openai'?'active':'pending')+'">'+esc(p.status)+'</span></div>';}).join('')+'</div>'+sectionHead('AI WORKSPACE','Draft • Analyze • Structure • Export','Closing an AI drafting window automatically preserves the current draft as a file. AI never expands the user’s data permissions and cannot perform final policy, finance, HR, safeguarding or external-report approvals.')+'<div class="grid-2"><div class="card panel"><h4>Quick actions</h4><div class="ai-quick-grid">'+[['report','Draft a results report'],['project','Develop a project concept'],['project-document','Draft a project document'],['policy','Review policy wording'],['finance','Draft finance / budget material'],['general','General writing support']].map(function(x){return '<button class="btn secondary" onclick="openAIAssistant(\''+x[0]+'\')">✦ '+esc(x[1])+'</button>';}).join('')+'</div></div><div class="notice"><h4>Human control remains mandatory</h4><p>AI output is a draft. Responsible staff must verify evidence, financial figures, law, donor terms, country requirements, safeguarding and approval authority before use.</p></div></div>'+sectionHead('MY AI FILES',files.length+' saved file(s)','Server mode creates DOCX/XLSX files. Standalone browser mode preserves Word/Excel-compatible files in IndexedDB.')+'<div class="card panel">'+(files.length?files.map(function(f){return '<div class="ai-file-row"><div><span class="scope-pill">'+esc(String(f.format||'word').toUpperCase())+'</span><b>'+esc(f.fileName||f.title||'AI document')+'</b><small>'+longDateTime(f.createdAt)+' • '+esc(f.storage||'browser')+'</small></div><div class="doc-actions"><button class="btn small" onclick="downloadAIFile(\''+f.id+'\')">Download</button><button class="btn small danger" onclick="deleteAIFile(\''+f.id+'\')">Delete</button></div></div>';}).join(''):'<div class="empty"><b>No AI files yet</b>Generate a draft; it can be saved as Word or Excel.</div>')+'</div>'+sectionHead('MY RECENT AI DRAFTS',history.length+' saved draft(s)','Draft text remains editable and can be exported again at any time.')+'<div class="card panel">'+(history.length?history.map(function(h){return '<div class="history-item"><div class="history-head"><div><span>'+esc(h.kind||'AI')+'</span><b>'+esc(h.task||'Draft assistance')+'</b><small>'+longDateTime(h.createdAt)+'</small></div><div class="doc-actions"><button class="btn small secondary" onclick="editAIHistory(\''+h.id+'\')">Edit</button><button class="btn small" onclick="exportAIHistory(\''+h.id+'\',\'word\')">Word</button><button class="btn small" onclick="exportAIHistory(\''+h.id+'\',\'excel\')">Excel</button><button class="btn small danger" onclick="deleteAIHistory(\''+h.id+'\')">Delete</button></div></div><p>'+esc(String(h.output||'').slice(0,900))+'</p></div>';}).join(''):'<div class="empty"><b>No AI drafts yet</b>Start AI Assistance to create the first draft.</div>')+'</div>';}
function aiTemplate(kind){var map={report:'Prepare a results-based report using: Executive Summary; Context; Outcomes/Outputs; Indicator performance (baseline/target/actual/variance/evidence); SDG contribution; Leave No One Behind; finance; risk; safeguarding; partnerships; evidence; lessons; next actions.',project:'Develop a project/programme concept using: situation analysis; theory of change; impact/goal; outcomes; outputs; activities; indicators/baselines/targets; SDGs; LNOB; beneficiaries; partners; budget; risk; safeguarding; MEAL; sustainability; reporting.','project-document':'Draft the selected project document with clear controlled headings, results logic, evidence, responsibilities, budget/risk considerations and approval requirements.',policy:'Review the controlled-policy wording for clarity, internal consistency, roles, evidence, version control, implementation and country-application considerations. Do not approve or make legal claims.',finance:'Draft a concise financial narrative covering purpose, budget line, funding source/award, procurement basis, allowability, evidence, variance, approvals and reconciliation. Do not authorize a transaction.',general:'Provide clear professional drafting assistance. Keep facts separate from assumptions and identify items requiring verification.'};return map[kind]||map.general;}

function aiRecommendedFormat(kind,preferred){var k=String(kind||'').toLowerCase(),p=String(preferred||'').toLowerCase();if(k.indexOf('finance')>=0||k.indexOf('budget')>=0||k.indexOf('data')>=0||p.indexOf('table')>=0||p.indexOf('spreadsheet')>=0)return'excel';return'word';}
function safeFileBase(x){return String(x||'Tech4Future-Global AI Draft').replace(/[\\/:*?"<>|]+/g,'-').replace(/\s+/g,' ').trim().slice(0,90)||'Tech4Future-Global AI Draft';}
function aiBrowserWordFile(title,content){var html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#000;line-height:1.55;padding:36px}h1{color:#073b80;font-size:24px}pre{font-family:Arial,sans-serif;white-space:pre-wrap;font-size:11pt}</style></head><body><h1>'+esc(title)+'</h1><pre>'+esc(content)+'</pre></body></html>';return new File([html],safeFileBase(title)+'.doc',{type:'application/msword'});}
function aiBrowserExcelFile(title,content){var rows=String(content||'').split(/\r?\n/).map(function(x){return '<tr><td>'+esc(x)+'</td></tr>';}).join(''),html='<html><head><meta charset="utf-8"></head><body><table><tr><th>'+esc(title)+'</th></tr>'+rows+'</table></body></html>';return new File([html],safeFileBase(title)+'.xls',{type:'application/vnd.ms-excel'});}
function activeAIDraftPayload(){var result=$('#aiResult'),task=$('#aiTask'),kind=$('#aiKind'),out=$('#aiOutput'),fmt=$('#aiFileFormat');if(!result||!result.value.trim())return null;return {title:(task&&task.value.trim())||'Tech4Future-Global AI Draft',content:result.value.trim(),kind:(kind&&kind.value)||'general',preferredOutput:(out&&out.value)||'',format:(fmt&&fmt.value)||'auto'};}
function aiFingerprint(x){return x?String(x.kind)+'|'+String(x.title)+'|'+String(x.content.length)+'|'+String(x.content.slice(0,120)):'';}
async function persistAIFile(payload,format,downloadIt){if(!payload||!payload.content)return null;format=format==='auto'?aiRecommendedFormat(payload.kind,payload.preferredOutput):format;var m={id:uuid(),userId:session.id,orgId:session.orgId,title:payload.title,kind:payload.kind,format:format,createdAt:nowISO(),storage:'browser',fileName:'',serverUrl:''};try{var res=await fetch('/api/exports/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({format:format,title:payload.title,content:payload.content,kind:payload.kind,user:{id:session.id,name:session.name,organization:orgById(session.orgId)&&orgById(session.orgId).name,position:positionTitle()}})});if(res.ok){var j=await res.json();m.id=j.fileId||m.id;m.fileName=j.fileName||safeFileBase(payload.title)+(format==='excel'?'.xlsx':'.docx');m.serverUrl=j.downloadUrl||'';m.storage='server';db.aiFiles=db.aiFiles||[];db.aiFiles.unshift(m);save();logAction('Saved AI file',m.fileName);if(downloadIt&&m.serverUrl){var a=document.createElement('a');a.href=m.serverUrl;a.download=m.fileName;document.body.appendChild(a);a.click();a.remove();}return m;}}catch(e){}var file=format==='excel'?aiBrowserExcelFile(payload.title,payload.content):aiBrowserWordFile(payload.title,payload.content);m.fileName=file.name;m.storage='browser IndexedDB';await putBlob('aiFiles',m.id,file);db.aiFiles=db.aiFiles||[];db.aiFiles.unshift(m);save();logAction('Saved AI file',m.fileName);if(downloadIt)downloadBlob(file,file.name);return m;}
async function exportAIResult(format){var p=activeAIDraftPayload();if(!p){toast('Generate or enter a draft first.');return;}var f=await persistAIFile(p,format,true);if(f){if(activeAIDraftState)activeAIDraftState.lastSavedFingerprint=aiFingerprint(p);toast('AI file saved as '+f.fileName+'.');}}
async function autoSaveActiveAIDraft(){var p=activeAIDraftPayload();if(!p)return;var fp=aiFingerprint(p);if(activeAIDraftState&&activeAIDraftState.lastSavedFingerprint===fp)return;var fmt=p.format==='auto'?aiRecommendedFormat(p.kind,p.preferredOutput):p.format,f=await persistAIFile(p,fmt,false);if(activeAIDraftState){activeAIDraftState.lastSavedFingerprint=fp;activeAIDraftState.fileId=f&&f.id||'';}}
async function downloadAIFile(id){var m=(db.aiFiles||[]).find(function(x){return x.id===id;});if(!m)return;if(m.serverUrl){var a=document.createElement('a');a.href=m.serverUrl;a.download=m.fileName||'';document.body.appendChild(a);a.click();a.remove();return;}var f=await getBlob('aiFiles',id);if(!f){toast('The AI file is not available in this browser.');return;}downloadBlob(f.blob,f.name||m.fileName);}
function deleteAIFile(id){var m=(db.aiFiles||[]).find(function(x){return x.id===id;});if(!m)return;if(!window.confirm('Delete this saved AI file reference?'))return;db.aiFiles=db.aiFiles.filter(function(x){return x.id!==id;});save();logAction('Deleted AI file',m.fileName||id);render('ai');}
async function exportAIHistory(id,format){var h=(db.aiHistory||[]).find(function(x){return x.id===id;});if(!h)return;var f=await persistAIFile({title:h.task||'AI Draft',content:h.output||'',kind:h.kind||'general',preferredOutput:'',format:format},format,true);if(f)toast('AI draft exported as '+f.fileName+'.');}
function openAIAssistant(kind){activeAIDraftState={kind:kind||'general',lastSavedFingerprint:''};showModal('AI ASSISTANCE','ChatGPT / AI Draft Assistant','<form id="aiAssistForm" class="form-grid ai-assist-form"><div class="credential-box full"><b>Active mode:</b> the form first calls the secure T4F AI gateway. If the gateway is unavailable, it produces a local structured draft. Closing this AI window automatically preserves the current draft as a Word- or Excel-compatible file.</div><label>Task type<input id="aiKind" value="'+esc(kind||'general')+'" disabled></label><label>Preferred output<select id="aiOutput"><option>Professional narrative</option><option>Structured template</option><option>Executive summary</option><option>Review comments</option><option>Action plan</option><option>Table-ready content</option></select></label><label>File format<select id="aiFileFormat"><option value="auto">Auto — Word or Excel</option><option value="word">Word</option><option value="excel">Excel</option></select></label><label class="full">What do you want AI to do?<textarea id="aiTask" rows="4" required>'+esc(aiTemplate(kind||'general'))+'</textarea></label><label class="full">Authorized context / source material<textarea id="aiContext" rows="8" placeholder="Paste only information you are authorized to use. Do not include passwords, bank credentials or unnecessary sensitive case identities."></textarea></label><div class="form-actions"><button class="btn primary">Generate Draft</button></div><div id="aiStatus" class="full ai-status"></div><label class="full">AI draft<textarea id="aiResult" rows="18" placeholder="Generated content will appear here."></textarea></label><div class="credential-box full"><b>Automatic file rule:</b> narrative/report/policy/project drafts default to Word; finance/budget/data/table outputs default to Excel. You may override the format above.</div><div class="form-actions"><button type="button" class="btn" onclick="copyAIResult()">Copy Draft</button><button type="button" class="btn secondary" onclick="saveAIResult()">Save Draft Record</button><button type="button" class="btn secondary" onclick="exportAIResult(\'word\')">Save + Download Word</button><button type="button" class="btn secondary" onclick="exportAIResult(\'excel\')">Save + Download Excel</button></div></form>');$('#aiAssistForm').onsubmit=async function(e){e.preventDefault();var task=$('#aiTask').value.trim(),context=$('#aiContext').value.trim(),status=$('#aiStatus');status.textContent='Generating…';try{var res=await fetch('/api/v1/ai/assist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:kind||'general',task:task,context:context,output:$('#aiOutput').value,user:{id:session.id,organization:orgById(session.orgId)&&orgById(session.orgId).name,position:positionTitle()}})});if(!res.ok)throw new Error('Gateway unavailable');var j=await res.json();$('#aiResult').value=j.output||'';status.textContent='Live AI draft generated through secure gateway. The draft will auto-save when this window closes.';}catch(err){$('#aiResult').value=localAIDraft(task,context);status.textContent='Secure AI gateway was not reachable; local structured drafting fallback generated this working draft. The draft will auto-save when this window closes.';}};}
function editAIHistory(id){var h=(db.aiHistory||[]).find(function(x){return x.id===id;});if(!h)return;showModal('AI ASSISTANCE','Edit Saved AI Draft','<form id="aiHistoryEdit" class="form-grid"><label class="full">Title / task<input id="aihTask" value="'+esc(h.task||'')+'"></label><label class="full">Saved draft<textarea id="aihOutput" rows="20">'+esc(h.output||'')+'</textarea></label><div class="form-actions"><button class="btn primary">Save Changes</button></div></form>');$('#aiHistoryEdit').onsubmit=function(e){e.preventDefault();h.task=$('#aihTask').value.trim();h.output=$('#aihOutput').value;h.updatedAt=nowISO();save();logAction('Edited saved AI draft',h.task);closeModal();render('ai');};}
function deleteAIHistory(id){var h=(db.aiHistory||[]).find(function(x){return x.id===id;});if(!h)return;if(!window.confirm('Delete this saved AI draft?'))return;db.aiHistory=db.aiHistory.filter(function(x){return x.id!==id;});save();logAction('Deleted saved AI draft',h.task||id);render('ai');toast('AI draft deleted.');}

function copyAIResult(){var el=$('#aiResult');if(!el)return;copyText(el.value);}
function saveAIResult(){var p=activeAIDraftPayload();if(!p){toast('Generate or enter a draft first.');return;}db.aiHistory=db.aiHistory||[];db.aiHistory.unshift({id:uuid(),userId:session.id,orgId:session.orgId,kind:p.kind,task:p.title,output:p.content,preferredFormat:p.format==='auto'?aiRecommendedFormat(p.kind,p.preferredOutput):p.format,createdAt:nowISO()});save();logAction('Saved AI draft',p.title);toast('AI draft record saved.');}

/* profile */
function renderProfile(){var u=userById(session.id),o=orgById(u.orgId),p=positionById(u.positionId),pr=u.profile||{};return pageHeader('MY ACCOUNT','Profile & Terms of Reference','Profile photo, education, qualifications, certifications, experience and assigned Terms of Reference.', '<button class="btn secondary" onclick="openProfileEditor()">Edit Profile</button><button class="btn secondary" onclick="openPasswordChange()">Change Password</button>')+'<div class="card panel" style="margin-top:17px"><div class="profile-header"><div class="profile-photo" '+avatarStyle(u)+'>'+((pr.photo)?'':initials(u.name))+'</div><div class="profile-meta"><h3>'+esc(u.name)+'</h3><p>'+esc(p&&p.title||specialPositionLabel(u))+'<br>'+esc(o&&o.name||'')+' • '+esc(pr.country||o&&o.country||'')+'</p><div class="profile-tags"><span class="scope-pill">'+esc((u.systemRole||'standard_user').replace(/_/g,' '))+'</span>'+(p?'<span class="scope-pill">'+esc(p.group)+'</span>':'')+statusPill(u.status)+'</div><div class="info-grid" style="margin-top:15px"><div class="info-item"><span>Education</span><b>'+esc(pr.education||'Not added')+'</b></div><div class="info-item"><span>Qualifications</span><b>'+esc(pr.qualifications||'Not added')+'</b></div><div class="info-item"><span>Certifications</span><b>'+esc(pr.certifications||'Not added')+'</b></div><div class="info-item"><span>Experience</span><b>'+esc(pr.experience||'Not added')+'</b></div><div class="info-item"><span>Phone</span><b>'+esc(pr.phone||'Not added')+'</b></div><div class="info-item"><span>Appointment / Term</span><b>'+esc([pr.appointmentDate,pr.termStart&&'Start '+pr.termStart,pr.termEnd&&'End '+pr.termEnd].filter(Boolean).join(' • ')||'Not added')+'</b></div></div>'+(pr.bio?'<div class="tor-section"><h4>Professional profile</h4><p>'+esc(pr.bio)+'</p></div>':'')+'</div></div></div>'+sectionHead('POSITION TERMS OF REFERENCE','My assigned TOR',p&&p.reportsTo||'External/system role')+'<div class="card panel">'+torFull(p)+'</div>'+(isClockUser()?clockWidget():'');}
function openProfileEditor(){var u=userById(session.id),p=u.profile||{};showModal('PROFILE','Edit profile','<form id="profileForm" class="form-grid"><label class="full">Profile photo<input id="profilePhoto" type="file" accept="image/*"></label><label>Phone<input id="profilePhone" value="'+esc(p.phone||'')+'"></label><label>Country<input id="profileCountry" value="'+esc(p.country||'')+'"></label><label>City<input id="profileCity" value="'+esc(p.city||'')+'"></label><label>LinkedIn / professional URL<input id="profileLinkedin" value="'+esc(p.linkedin||'')+'"></label><label>Office address<input id="profileOfficeAddress" value="'+esc(p.officeAddress||'')+'"></label><label>Fax<input id="profileFax" value="'+esc(p.fax||'')+'"></label><label class="full">Education<textarea id="profileEducation" rows="3">'+esc(p.education||'')+'</textarea></label><label class="full">Qualifications<textarea id="profileQualifications" rows="3">'+esc(p.qualifications||'')+'</textarea></label><label class="full">Certifications<textarea id="profileCertifications" rows="3">'+esc(p.certifications||'')+'</textarea></label><label class="full">Professional experience<textarea id="profileExperience" rows="4">'+esc(p.experience||'')+'</textarea></label><label class="full">Biography / professional profile<textarea id="profileBio" rows="4">'+esc(p.bio||'')+'</textarea></label><label>Appointment date<input id="profileAppointment" type="date" value="'+esc(p.appointmentDate||'')+'"></label><label>Term start<input id="profileTermStart" type="date" value="'+esc(p.termStart||'')+'"></label><label>Term end<input id="profileTermEnd" type="date" value="'+esc(p.termEnd||'')+'"></label><div></div><div class="form-actions"><button class="btn primary">Save Profile</button></div></form>');$('#profileForm').onsubmit=async function(e){e.preventDefault();var pr=u.profile||{},photo=$('#profilePhoto').files[0];if(photo){if(photo.size>2000000){toast('Use a profile image under 2 MB in this standalone version.');return;}pr.photo=await fileToDataURL(photo);}Object.assign(pr,{phone:$('#profilePhone').value.trim(),country:$('#profileCountry').value.trim(),city:$('#profileCity').value.trim(),linkedin:$('#profileLinkedin').value.trim(),officeAddress:$('#profileOfficeAddress').value.trim(),fax:$('#profileFax').value.trim(),education:$('#profileEducation').value.trim(),qualifications:$('#profileQualifications').value.trim(),certifications:$('#profileCertifications').value.trim(),experience:$('#profileExperience').value.trim(),bio:$('#profileBio').value.trim(),appointmentDate:$('#profileAppointment').value,termStart:$('#profileTermStart').value,termEnd:$('#profileTermEnd').value});u.profile=pr;save();session=clone(u);applySessionLabels();logAction('Updated profile','Profile photo / qualifications / professional details');closeModal();render('profile');};}
function fileToDataURL(file){return new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(){resolve(r.result);};r.onerror=function(){reject(r.error);};r.readAsDataURL(file);});}
function openPasswordChange(){showModal('SECURITY','Change password','<form id="passwordForm" class="form-grid"><label class="full">Current password<input id="pwCurrent" type="password" required></label><label class="full">New password (only 8 characters)<input id="pwNew" type="password" minlength="8" maxlength="8" required></label><label class="full">Confirm new password<input id="pwNew2" type="password" minlength="8" maxlength="8" required></label><div id="pwError" class="form-error full"></div><div class="form-actions"><button class="btn primary">Update Password</button></div></form>');$('#passwordForm').onsubmit=async function(e){e.preventDefault();var current=$('#pwCurrent').value,next=$('#pwNew').value;if(next!==$('#pwNew2').value){$('#pwError').textContent='New passwords do not match.';return;}if(next.length!==8){$('#pwError').textContent='Password must be only 8 characters long.';return;}try{if(window.T4FBackend&&window.T4FBackend.token())await window.T4FBackend.changePassword(current,next);else{var u0=userById(session.id);if(current!==u0.password){$('#pwError').textContent='Current password is incorrect.';return;}}}catch(err){$('#pwError').textContent=err.message||'Password update failed.';return;}var u=userById(session.id);if(u)u.password=next;save();logAction('Changed password','User changed password');closeModal();toast('Password changed.');};}

/* audit/search */
function renderAudit(){var rows=isPlatformAdmin()?db.audit:db.audit.filter(function(a){var o=orgById(session.orgId);return a.organization===(o&&o.name||'');});return pageHeader('CONTROL EVIDENCE','Audit Log','Prototype activity history. Production audit logging must be server-side and immutable.')+sectionHead('ACTIVITY',rows.length+' event(s)','Actions are restricted by administrator scope.')+'<div class="card panel">'+(rows.length?rows.map(function(a){return '<div class="request-item" style="grid-template-columns:150px 140px 1fr 180px"><span>'+new Date(a.time).toLocaleString()+'</span><b>'+esc(a.actor)+'</b><div><b>'+esc(a.action)+'</b><small style="display:block;color:var(--muted)">'+esc(a.detail)+'</small></div><span>'+esc(a.organization)+'</span></div>';}).join(''):'<div class="empty"><b>No audit events</b></div>')+'</div>';}
$('#globalSearch').addEventListener('input',function(e){var q=e.target.value.trim().toLowerCase();if(!q){render(currentPage);return;}var results=[];if(can('accounts'))db.users.filter(function(u){return isPlatformAdmin()||visibleOrgIds().indexOf(u.orgId)>=0;}).forEach(function(u){if(JSON.stringify(u).toLowerCase().indexOf(q)>=0)results.push(['User',u.name,u.email+' • '+positionTitle(u)]);});DATA.positions.forEach(function(p){if((p.title+' '+p.rolePurpose).toLowerCase().indexOf(q)>=0)results.push(['Position',p.title,p.group]);});if(can('documents'))db.documents.forEach(function(d){if((d.id+' '+d.name+' '+d.type+' '+d.categoryCode+' '+d.category).toLowerCase().indexOf(q)>=0)results.push(['Document',d.name,d.id+' • '+d.category]);});visibleReports().forEach(function(r){if((r.title+' '+r.summary).toLowerCase().indexOf(q)>=0)results.push(['Report',r.title,r.period+' • '+r.reportDate]);});visibleProjects().forEach(function(p){if((p.name+' '+p.goal).toLowerCase().indexOf(q)>=0)results.push(['Project',p.name,orgById(p.orgId)&&orgById(p.orgId).name||'']);});$('#pageKicker').textContent='SEARCH';$('#pageTitle').textContent='Search Results';$('#content').innerHTML=pageHeader('PORTAL SEARCH','Search Results','Results never expand your assigned data permissions.')+sectionHead('RESULTS',results.length+' matches')+'<div class="card panel">'+(results.slice(0,100).map(function(r){return '<div class="request-item" style="grid-template-columns:90px 1fr"><span class="scope-pill">'+esc(r[0])+'</span><div><b>'+esc(r[1])+'</b><small style="display:block;color:var(--muted)">'+esc(r[2])+'</small></div></div>';}).join('')||'<div class="empty"><b>No results</b></div>')+'</div>';});

/* utility print/download */
function downloadBlob(blob,name){var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},10000);}
function printHtml(title,body){var w=window.open('','_blank','width=1000,height=800');if(!w){toast('Allow pop-ups to print this record.');return;}w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+esc(title)+'</title><style>body{font-family:Arial,sans-serif;color:#14213d;padding:36px;line-height:1.5}h1,h2,h3{font-family:Georgia,serif;color:#0b3d8e}.document-preview{max-width:900px;margin:auto}.doc-preview-head{display:flex;justify-content:space-between;border-bottom:3px solid #0b4fa3;padding-bottom:14px;margin-bottom:18px}.doc-preview-head span{font-size:11px;letter-spacing:2px}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.info-item{border:1px solid #dce5ef;padding:10px;border-radius:8px}.info-item span{display:block;font-size:9px;color:#6d7b90}.finance-amount{font-size:38px;font-weight:bold;color:#0b4fa3;margin:22px 0}.tor-section{margin:14px 0}.finance-coding{display:flex;gap:20px;font-size:11px;border-top:1px solid #ddd;padding-top:12px}@media print{button{display:none}}</style></head><body>'+body+'</body></html>');w.document.close();setTimeout(function(){w.focus();w.print();},350);}

/* modal */
function showModal(kicker,title,html){$('#modalKicker').textContent=kicker;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.add('show');}
function closeModal(){if(forceReset)return;var hasAIDraft=activeAIDraftState&&$('#aiResult')&&$('#aiResult').value.trim();if(hasAIDraft)autoSaveActiveAIDraft();$('#modal').classList.remove('show');if(activeAIDraftState)setTimeout(function(){activeAIDraftState=null;},600);}
$('#modalClose').onclick=closeModal;$('#modal').addEventListener('click',function(e){if(e.target.id==='modal')closeModal();});

/* restore */
try{var s=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');if(s){var u=userById(s.id);if(u&&u.status!=='Inactive'){session=clone(u);viewedOrgId=u.orgId;openPortal();if(u.mustReset)forcePasswordChange();}else showInitialScreen();}else showInitialScreen();}catch(e){showInitialScreen();}

